function qualityIdFromLabel(label=''){const s=String(label);if(s.includes('地阶'))return 'di';if(s.includes('玄阶'))return 'xuan';if(s.includes('黄阶'))return 'huang';if(s.includes('凡阶'))return 'fan';return 'mundane'}
function reverseLookup(map,id){for(const [name,value] of Object.entries(map))if(value===id)return name;return null}
function realmIdFromIndex(index){return REALM_IDS[clamp(Number(index)||0,0,REALM_IDS.length-1)]}
function regionIdFromName(name){return REGION_ID_BY_NAME[name]||null}
function manualIdFromName(name){return V31_MANUAL_ID_BY_NAME[name]||MANUAL_ID_BY_NAME[name]||null}
function spellIdFromName(name){return V31_SPELL_ID_BY_NAME[name]||SPELL_ID_BY_NAME[name]||null}
function gearItemIdFromKey(key){return ITEM_ID_BY_GEAR_KEY[key]||null}
function artifactIdFromGearKey(key){return ARTIFACT_ID_BY_GEAR_KEY[key]||null}
function manualRegistry(){const out={};for(const [name,d] of Object.entries(MANUALS)){const id=manualIdFromName(name);if(!id)continue;const meta=v31ManualCatalogRow(id)||{};out[id]={id,manualId:id,name,type:'manual',qualityId:qualityIdFromLabel(d.quality),qualityLabel:d.quality,mult:d.mult,desc:d.desc,unlock:Number(meta.unlock)||0,realmRequirement:realmIdFromIndex(meta.unlock||0),path:meta.path||'none',sources:[...(meta.sources||[])],cost:v31DefaultCost(meta,'manual'),effects:JSON.parse(JSON.stringify(meta.effects||{}))}}return out}
function spellRegistry(){const out={};for(const [name,d] of Object.entries(SPELLS)){const id=spellIdFromName(name);if(!id)continue;const meta=v31SpellCatalogRow(id)||{},old=SPELL_FOUNDATION_META[id]||{};out[id]={id,spellId:id,name,type:'spell',qualityId:qualityIdFromLabel(d.quality),qualityLabel:d.quality,qi:d.qi||0,power:d.power||0,desc:d.desc,category:meta.category||old.category||'utility',cooldown:Number(meta.cooldown??old.cooldown)||0,statusIds:[...(meta.statusIds||old.statusIds||[])],path:meta.path||old.path||'none',unlock:Number(meta.unlock)||0,realmRequirement:realmIdFromIndex(meta.unlock||0),sources:[...(meta.sources||[])],cost:v31DefaultCost(meta,'spell'),effect:JSON.parse(JSON.stringify(meta.effect||{}))}}return out}
function realmRegistry(){const out={};REALMS.forEach((d,i)=>{const id=REALM_IDS[i];out[id]={id,realmId:id,index:i,name:d.name,need:d.need,rate:d.rate,maxHp:d.maxHp,maxQi:d.maxQi}});return out}
function regionRegistry(){const out={};for(const [name,d] of Object.entries(LOCATIONS)){const id=regionIdFromName(name);out[id]={id,regionId:id,name,type:'region',danger:d.danger,faction:d.faction,specialty:d.specialty,links:Object.keys(d.links||{}).map(regionIdFromName).filter(Boolean)}}return out}
