function artifactRegistry(){const out={};for(const row of V32_EQUIPMENT_CATALOG.filter(x=>x.trueArtifact))out[row.artifactId]={id:row.artifactId,artifactId:row.artifactId,itemId:row.itemId,name:row.name,type:'artifact',artifactSlot:row.artifactSlot,qualityId:row.qualityId,tier:row.tier,realmRequirement:realmIdFromIndex(row.unlock),path:row.path,sources:[...row.sources],activeAbility:row.active?JSON.parse(JSON.stringify(row.active)):null,passiveEffects:JSON.parse(JSON.stringify(row.passive||{})),refinement:{supported:true,maxLayer:9},binding:{supported:true,birthArtifact:true},warmth:{supported:true,max:100},damageState:{supported:true,repairable:true}};return out}
