function rewardEntries(e){const r=e.reward||{},out=[];const add=(id,v,mode='fixed')=>{if(Array.isArray(v)&&((v[0]||0)!==0||(v[1]||0)!==0))out.push({materialId:id,min:v[0]||0,max:v[1]||0,mode});else if(Number(v)>0)out.push({materialId:id,min:Number(v),max:Number(v),mode})};add('mat-spirit-stone',r.stones);add('mat-spirit-herb',r.herbs);add('mat-core-essence',r.core);add('mat-nascent-essence',r.nascent);add('mat-deification-essence',r.deification);if(!e.nonLethal)out.push({materialId:'mat-rare-material',min:0,max:e.realm>=23?2:e.realm>=15?1:0,mode:'realm-scaled'});return out.concat(v33MaterialDropEntries(e))}
