function syncStableContentState(){if(!state?.player)return false;const p=state.player;p.contentStateVersion=CONTENT_STATE_VERSION;p.realmId=realmIdFromIndex(p.realmIndex);p.regionId=regionIdFromName(p.location);p.manualId=manualIdFromName(p.manual);p.spellProficiencyById={};for(const [name,prof] of Object.entries(p.spells||{})){const id=spellIdFromName(name);if(id)p.spellProficiencyById[id]=Number(prof)||0}if(p.materialInventoryById&&typeof p.materialInventoryById==='object')p.materialCountsById={...p.materialInventoryById};else{p.materialCountsById={};for(const d of Object.values(MATERIAL_REGISTRY))if(d.field)p.materialCountsById[d.id]=Math.max(0,Number(p[d.field])||0)}if(p.pillInventoryById&&typeof p.pillInventoryById==='object'){p.itemCountsById={};for(const r of V33_RECIPE_CATALOG)p.itemCountsById[r.itemId]=Object.values(p.pillInventoryById[r.id]||{}).reduce((a,n)=>a+(Number(n)||0),0)}else{p.itemCountsById={};for(const d of Object.values(CONSUMABLE_ITEM_META))p.itemCountsById[d.id]=Math.max(0,Number(p[d.field])||0)}if(!Array.isArray(p.gearOwnedIds)||!p.gearOwnedIds.length)p.gearOwnedIds=(Array.isArray(p.gearOwned)?p.gearOwned:[]).map(gearItemIdFromKey).filter(Boolean);if(!p.equippedItemIds||typeof p.equippedItemIds!=='object'||Array.isArray(p.equippedItemIds)){const eq=p.equipped||{};p.equippedItemIds={weapon:gearItemIdFromKey(eq.weapon),armor:gearItemIdFromKey(eq.armor),charm:gearItemIdFromKey(eq.charm)}}if(!Array.isArray(p.artifactOwnedIds))p.artifactOwnedIds=(Array.isArray(p.gearOwned)?p.gearOwned:[]).map(artifactIdFromGearKey).filter(Boolean);return true}
function ensureContentStateShape(){if(!state?.player)return false;const p=state.player;if(p.contentStateVersion==null)p.contentStateVersion=CONTENT_STATE_VERSION;if(!p.spellProficiencyById||typeof p.spellProficiencyById!=='object'||Array.isArray(p.spellProficiencyById))p.spellProficiencyById={};if(!p.materialCountsById||typeof p.materialCountsById!=='object'||Array.isArray(p.materialCountsById))p.materialCountsById={};if(!p.itemCountsById||typeof p.itemCountsById!=='object'||Array.isArray(p.itemCountsById))p.itemCountsById={};if(!Array.isArray(p.gearOwnedIds))p.gearOwnedIds=[];if(!p.equippedItemIds||typeof p.equippedItemIds!=='object'||Array.isArray(p.equippedItemIds))p.equippedItemIds={weapon:null,armor:null,charm:null};if(!Array.isArray(p.artifactOwnedIds))p.artifactOwnedIds=[];return syncStableContentState()}
function ensureCombatFoundation(){if(!combat)return null;if(!combat.cooldowns||typeof combat.cooldowns!=='object')combat.cooldowns={};if(!combat.statuses||typeof combat.statuses!=='object')combat.statuses={};return combat}
function skillCooldownRemaining(skillId){const c=ensureCombatFoundation();return c?Math.max(0,Number(c.cooldowns[skillId])||0):0}
function setSkillCooldown(skillId,turns=null){const c=ensureCombatFoundation(),d=spellRegistry()[skillId];if(!c||!d)return 0;const n=Math.max(0,Number(turns==null?d.cooldown:turns)||0);c.cooldowns[skillId]=n;return n}
function tickSkillCooldowns(){const c=ensureCombatFoundation();if(!c)return {};for(const id of Object.keys(c.cooldowns)){c.cooldowns[id]=Math.max(0,(Number(c.cooldowns[id])||0)-1);if(c.cooldowns[id]===0)delete c.cooldowns[id]}return {...c.cooldowns}}
function applyCombatStatus(statusId,duration=null,sourceId=null){const c=ensureCombatFoundation(),d=v31AllStatusRegistry()[statusId];if(!c||!d)return null;const turns=Math.max(1,Number(duration==null?d.defaultDuration:duration)||1),old=c.statuses[statusId];c.statuses[statusId]={id:statusId,turns:d.stack==='stack'?(old?.turns||0)+turns:Math.max(old?.turns||0,turns),sourceId:sourceId||null};return {...c.statuses[statusId]}}
function combatStatusTurns(statusId){const c=ensureCombatFoundation();return c&&c.statuses[statusId]?Math.max(0,Number(c.statuses[statusId].turns)||0):0}
function tickCombatStatuses(){const c=ensureCombatFoundation();if(!c)return {};for(const id of Object.keys(c.statuses)){c.statuses[id].turns=Math.max(0,(Number(c.statuses[id].turns)||0)-1);if(c.statuses[id].turns===0)delete c.statuses[id]}return JSON.parse(JSON.stringify(c.statuses))}
function artifactPassiveEffects(artifactId){const d=artifactRegistry()[artifactId];return d?{...d.passiveEffects}:null}
function artifactActiveAbility(artifactId){const d=artifactRegistry()[artifactId];return d?d.activeAbility:null}
