const V31_MANUAL_BY_ID=Object.freeze(Object.fromEntries(V31_MANUAL_CATALOG.map(x=>[x.id,x])));
const V31_MANUAL_ID_BY_NAME=Object.freeze(Object.fromEntries(V31_MANUAL_CATALOG.map(x=>[x.name,x.id])));
const V31_SPELL_BY_ID=Object.freeze(Object.fromEntries(V31_SPELL_CATALOG.map(x=>[x.id,x])));
const V31_SPELL_ID_BY_NAME=Object.freeze(Object.fromEntries(V31_SPELL_CATALOG.map(x=>[x.name,x.id])));
const V31_STATUS_REGISTRY=Object.freeze({
 'status-bind':{id:'status-bind',name:'缚灵',kind:'debuff',stack:'refresh',defaultDuration:1},
 'status-vulnerable':{id:'status-vulnerable',name:'破绽',kind:'debuff',stack:'refresh',defaultDuration:2},
 'status-regen':{id:'status-regen',name:'回生',kind:'buff',stack:'refresh',defaultDuration:2},
 'status-counter':{id:'status-counter',name:'反震',kind:'buff',stack:'refresh',defaultDuration:1},
 'status-rage':{id:'status-rage',name:'燃战',kind:'buff',stack:'refresh',defaultDuration:3},
 'status-shield':{id:'status-shield',name:'护盾',kind:'buff',stack:'refresh',defaultDuration:3},
 'status-qi-flow':{id:'status-qi-flow',name:'聚灵',kind:'buff',stack:'refresh',defaultDuration:1}
});
Object.assign(MANUALS,Object.fromEntries(V31_MANUAL_CATALOG.filter(x=>!x.legacy).map(x=>[x.name,{quality:x.quality,mult:x.mult,desc:x.desc}])));
Object.assign(SPELLS,Object.fromEntries(V31_SPELL_CATALOG.filter(x=>!x.legacy).map(x=>[x.name,{quality:x.quality,qi:x.qi||0,power:x.power||0,desc:x.desc}])));
let v31SelectedLoadoutSlot=0;

function v31AllStatusRegistry(){return {...STATUS_REGISTRY,...V31_STATUS_REGISTRY}}
function v31ManualCatalogRow(id){return V31_MANUAL_BY_ID[id]||null}
function v31SpellCatalogRow(id){return V31_SPELL_BY_ID[id]||null}
function v31ManualStageFromProf(prof=0){const n=Math.max(0,Number(prof)||0);return n>=700?3:n>=300?2:n>=100?1:0}
function v31ManualStageName(stage){return ['初窥','小成','大成','圆满'][clamp(Number(stage)||0,0,3)]}
function v31StageScale(stage){return [1,1.15,1.32,1.52][clamp(Number(stage)||0,0,3)]}
function v31ScaledEffects(raw={},scale=1){const out={};for(const [k,v] of Object.entries(raw||{})){if(k==='categoryDamage'&&v&&typeof v==='object'){out[k]={};for(const [a,b] of Object.entries(v))out[k][a]=(Number(b)||0)*scale}else if(typeof v==='number'&&!['injuryChance','cultivationHpCost'].includes(k))out[k]=v*scale;else out[k]=v}return out}
function v31CurrentManualMeta(){const id=manualIdFromName(state?.player?.manual);return id?v31ManualCatalogRow(id):null}
function v31CurrentManualEffects(){const meta=v31CurrentManualMeta(),stage=v31ManualStageFromProf(state?.player?.manualProf||0);return v31ScaledEffects(meta?.effects||{},v31StageScale(stage))}
function v31PassiveRow(){const id=state?.player?.passiveSkillId;return id?v31SpellCatalogRow(id):null}
function v31PassiveEffects(){const row=v31PassiveRow();return row?.effect?.passive?{...row.effect.passive}: {}}
function v31ManualHpMultiplier(){return Math.max(.45,1+(v31CurrentManualEffects().hp||0))}
function v31ManualQiMultiplier(){return Math.max(.45,1+(v31CurrentManualEffects().qi||0))}
function v31PassiveHpMultiplier(){return Math.max(.45,1+(v31PassiveEffects().hp||0))}
function v31PassiveQiMultiplier(){return Math.max(.45,1+(v31PassiveEffects().qi||0))}
function v31IncomingMultiplier(){const m=v31CurrentManualEffects(),p=v31PassiveEffects();return Math.max(.45,(1+(m.incoming||0))*(1+(p.incoming||0)))}
function v31HealingMultiplier(){const m=v31CurrentManualEffects(),p=v31PassiveEffects();return Math.max(.5,(1+(m.healing||0))*(1+(p.healing||0)))}
function v31BreakthroughBonus(){return Number(v31CurrentManualEffects().breakthrough||0)}
function v31HasEquippedArtifact(){const eq=state?.player?.equipped||{};return Object.values(eq).some(k=>k&&artifactIdFromGearKey(k))}
function v31SkillDamageMultiplier(def){const m=v31CurrentManualEffects(),pm=v31CurrentManualMeta(),p=v31PassiveEffects();let out=1;if(pm?.path&&pm.path!=='none'&&def?.path===pm.path)out*=1+(m.pathDamage||0);if(m.categoryDamage&&def?.category)out*=1+(m.categoryDamage[def.category]||0);if(v31HasEquippedArtifact())out*=1+(m.artifactDamage||0);if(p.damageAll)out*=1+p.damageAll;if(p.path&&def?.path===p.path)out*=1+(p.pathDamage||0);if(v31HasEquippedArtifact())out*=1+(p.artifactDamage||0);if(combat?.v31Rage>0)out*=1.15;if(combat?.v31Vulnerable>0)out*=1.18;return out}
function v31DefaultCost(row,kind='spell'){const u=Math.max(0,Number(row?.unlock)||0),manualKind=kind==='manual';return {stones:(manualKind?6:4)+u*(manualKind?3:2),insight:u>=10?1+Math.floor((u-10)/6):0,relic:u>=15?1+Math.floor((u-15)/5):0,rare:u>=19?1:0,days:u>=19?3:u>=10?2:1}}
function v31CostText(cost){const rows=['灵石 '+(cost.stones||0)];if(cost.insight)rows.push('悟道 '+cost.insight);if(cost.relic)rows.push('残片 '+cost.relic);if(cost.rare)rows.push('高阶灵材 '+cost.rare);rows.push(cost.days+' 日');return rows.join(' · ')}
function v31CostReady(cost){const p=state.player;return p.spiritStones>=(cost.stones||0)&&(p.insight||0)>=(cost.insight||0)&&(p.relicFragments||0)>=(cost.relic||0)&&(p.rareMaterials||0)>=(cost.rare||0)}
function v31PayCost(cost){const p=state.player;p.spiritStones-=cost.stones||0;p.insight-=cost.insight||0;p.relicFragments-=cost.relic||0;p.rareMaterials-=cost.rare||0}
function v31KnownSpellIds(){const out=[];for(const name of Object.keys(state?.player?.spells||{})){const id=spellIdFromName(name);if(id)out.push(id)}return [...new Set(out)]}
function v31KnownActiveSkillIds(){return v31KnownSpellIds().filter(id=>{const row=v31SpellCatalogRow(id);return id!=='spell-basic-melee'&&row?.category!=='passive'})}
function ensureV31GrowthShape(){if(!state?.player)return false;const p=state.player;p.contentStateVersion=CONTENT_STATE_VERSION;if(!Array.isArray(p.manualLibraryIds))p.manualLibraryIds=[];if(!p.manualProficiencyById||typeof p.manualProficiencyById!=='object'||Array.isArray(p.manualProficiencyById))p.manualProficiencyById={};const current=manualIdFromName(p.manual);if(current&&!p.manualLibraryIds.includes(current))p.manualLibraryIds.push(current);if(current&&p.manualProficiencyById[current]==null)p.manualProficiencyById[current]=Number(p.manualProf)||0;if(!Array.isArray(p.activeSkillIds))p.activeSkillIds=[];if(p.passiveSkillId===undefined)p.passiveSkillId=null;if(p.skillLoadoutVersion==null)p.skillLoadoutVersion=1;const learned=v31KnownActiveSkillIds();p.activeSkillIds=p.activeSkillIds.filter((id,i,a)=>learned.includes(id)&&a.indexOf(id)===i).slice(0,6);for(const id of learned){if(p.activeSkillIds.length>=6)break;if(!p.activeSkillIds.includes(id))p.activeSkillIds.push(id)}while(p.activeSkillIds.length<6)p.activeSkillIds.push(null);if(p.passiveSkillId){const row=v31SpellCatalogRow(p.passiveSkillId);if(!row||row.category!=='passive'||!v31KnownSpellIds().includes(p.passiveSkillId))p.passiveSkillId=null}return true}
function syncV31GrowthState(){if(!state?.player)return false;ensureV31GrowthShape();const p=state.player,current=manualIdFromName(p.manual);if(current){if(!p.manualLibraryIds.includes(current))p.manualLibraryIds.push(current);p.manualProficiencyById[current]=Number(p.manualProf)||0}const learned=v31KnownActiveSkillIds();p.activeSkillIds=(p.activeSkillIds||[]).filter((id,i,a)=>!id||(learned.includes(id)&&a.indexOf(id)===i)).slice(0,6);while(p.activeSkillIds.length<6)p.activeSkillIds.push(null);return true}
function learnV31Manual(id,force=false){ensureV31GrowthShape();const row=v31ManualCatalogRow(id),p=state.player;if(!row)return 'missing';if(p.manualLibraryIds.includes(id))return 'known';if(row.legacy&&!force)return 'legacy';if(!force){if(p.realmIndex<row.unlock)return 'realm';if(!(row.sources||[]).includes(p.location))return 'location';const cost=v31DefaultCost(row,'manual');if(!v31CostReady(cost))return 'cost';v31PayCost(cost);advanceDays(cost.days);if(state.flags.dead)return 'dead'}p.manualLibraryIds.push(id);p.manualProficiencyById[id]=p.manualProficiencyById[id]||0;addPersonal('【功法传承】你取得《'+row.name+'》完整传承，之后可以自由切换修炼。','major');save();render();return 'learned'}
function switchV31Manual(id,force=false){ensureV31GrowthShape();const row=v31ManualCatalogRow(id),p=state.player;if(!row||!p.manualLibraryIds.includes(id))return false;const old=manualIdFromName(p.manual);if(old)p.manualProficiencyById[old]=Number(p.manualProf)||0;p.manual=row.name;p.manualProf=Number(p.manualProficiencyById[id])||0;if(!force)advanceDays(1);p.hp=Math.min(p.hp,maxHp());p.qi=Math.min(p.qi,maxQi());addPersonal('你改修《'+row.name+'》，恢复该功法此前的熟练进度。','major');save();render();return true}
function learnV31Spell(id,force=false){ensureV31GrowthShape();const row=v31SpellCatalogRow(id),p=state.player;if(!row)return 'missing';const name=row.name;if(name in p.spells)return 'known';if(row.legacy&&!force)return 'legacy';if(!force){if(p.realmIndex<row.unlock)return 'realm';if(row.path&&row.path!=='none'&&p.daoPath!==row.path)return 'path';if(!(row.sources||[]).includes(p.location))return 'location';const cost=v31DefaultCost(row,'spell');if(!v31CostReady(cost))return 'cost';v31PayCost(cost);advanceDays(cost.days);if(state.flags.dead)return 'dead'}p.spells[name]=0;if(row.category==='passive'){if(!p.passiveSkillId)p.passiveSkillId=id}else{const empty=p.activeSkillIds.findIndex(x=>!x);if(empty>=0)p.activeSkillIds[empty]=id}addPersonal('【术法传承】你掌握了【'+name+'】。','major');save();render();return 'learned'}
function equipV31Skill(slot,id){ensureV31GrowthShape();const p=state.player,i=clamp(Number(slot)||0,0,5);if(id==null){p.activeSkillIds[i]=null;save();render();return true}const row=v31SpellCatalogRow(id);if(!row||row.category==='passive'||!v31KnownSpellIds().includes(id))return false;for(let x=0;x<6;x++)if(p.activeSkillIds[x]===id)p.activeSkillIds[x]=null;p.activeSkillIds[i]=id;save();render();return true}
function equipV31Passive(id){ensureV31GrowthShape();if(id==null){state.player.passiveSkillId=null;save();render();return true}const row=v31SpellCatalogRow(id);if(!row||row.category!=='passive'||!v31KnownSpellIds().includes(id))return false;state.player.passiveSkillId=id;save();render();return true}
function v31SpellEffect(id){return v31SpellCatalogRow(id)?.effect||{}}
function v31SpellName(id){return v31SpellCatalogRow(id)?.name||reverseLookup(SPELL_ID_BY_NAME,id)||null}
function v31SpellLearnableHere(row){if(!row||row.legacy||state.player.realmIndex<row.unlock)return false;if(row.path&&row.path!=='none'&&state.player.daoPath!==row.path)return false;return (row.sources||[]).includes(state.player.location)}
function v31ManualLearnableHere(row){return !!(row&&!row.legacy&&state.player.realmIndex>=row.unlock&&(row.sources||[]).includes(state.player.location))}
function v31EffectSummary(e={}){const out=[];if(e.hp)out.push('气血 '+Math.round(e.hp*100)+'%');if(e.qi)out.push('灵力 '+Math.round(e.qi*100)+'%');if(e.breakthrough)out.push('破境 +'+Math.round(e.breakthrough*100)+'%');if(e.pathDamage)out.push('同道术法 +'+Math.round(e.pathDamage*100)+'%');if(e.healing)out.push('恢复 +'+Math.round(e.healing*100)+'%');if(e.incoming)out.push('承伤 '+(e.incoming>0?'+':'')+Math.round(e.incoming*100)+'%');if(e.artifactDamage)out.push('法宝协同 +'+Math.round(e.artifactDamage*100)+'%');if(e.categoryDamage)for(const [k,v] of Object.entries(e.categoryDamage))out.push(k+' +'+Math.round(v*100)+'%');return out.join(' · ')||'无额外偏向'}
function applyV31ManualCultivationAftermath(){const e=v31CurrentManualMeta()?.effects||{},p=state.player;if(e.cultivationHpCost){const loss=Math.max(1,Math.floor(maxHp()*e.cultivationHpCost));p.hp=Math.max(1,p.hp-loss);addPersonal('《'+p.manual+'》运功激烈，额外损耗气血 '+loss+'。','bad')}if(e.injuryChance&&rand()<e.injuryChance){p.injury=clamp((p.injury||0)+1,0,3);addPersonal('《'+p.manual+'》强行运转留下暗伤，当前伤势：'+injuryLabel()+'。','bad')}}
function v31DamageForSkill(def,effect,enemy,prof){const p=state.player,hits=Math.max(1,Number(effect.hits)||1),power=Math.max(1,Number(def.power)||1),melee=effect.attackType==='melee';let total=0;for(let i=0;i<hits;i++){let base=power*(Number(effect.damageScale)||1)+rint(Math.max(1,Math.floor(power*.05)),Math.max(2,Math.floor(power*.14)))+p.realmIndex*(melee?5:4)+Math.floor(prof/(melee?15:12));if(melee)base+=gearAtk()*.55;let mult=realmSuppressionMultiplier(p.realmIndex,enemy.realm||0)*(melee?daoMeleeMultiplier():gearSpellMultiplier()*daoSpellMultiplier())*v31SkillDamageMultiplier(def)*v32EquippedDamageMultiplier(def)*v33BuffMultiplier('damage')*v34BuildDamageMultiplier(def,effect)*v36SpaceDamageMultiplier(effect)*v37DamageMultiplier(def,effect)*v38DamageMultiplier(effect);if(effect.executeBelow&&combat.enemyHp/enemy.hp<=effect.executeBelow)mult*=Number(effect.executeMult)||1.35;total+=Math.max(1,Math.floor(base*mult))}return total}
