function v34BuildScore(b){if(!state?.player||!b||state.player.daoPath!==b.path)return {score:0,active:false,mastered:false,parts:{}};const p=state.player,manual=manualIdFromName(p.manual),parts={manual:b.manuals.includes(manual),passive:p.passiveSkillId===b.passive,artifact:v34ArtifactPathEquipped(b.path),skills:b.skills.filter(id=>p.activeSkillIds.includes(id))};const score=(parts.manual?1:0)+(parts.passive?1:0)+(parts.artifact?1:0)+parts.skills.length;return {score,active:score>=3,mastered:score>=5,parts}}
function v34ActiveBuild(){ensureV34CombatShape();const rows=V34_BUILD_CATALOG.filter(b=>b.path===state.player.daoPath).map(b=>({build:b,...v34BuildScore(b)})).sort((a,b)=>b.score-a.score||a.build.id.localeCompare(b.build.id));return rows[0]?.active?rows[0]:null}
function v34BuildDamageMultiplier(def,effect={}){const a=v34ActiveBuild();if(!a)return 1;const cats=a.build.bonus.categories||[],category=def?.category||'',path=def?.path||'none';let bonus=0;if(cats.includes(category))bonus+=a.build.bonus.damage||0;if(path===a.build.path&&category!=='passive')bonus+=a.mastered?.04:.02;return 1+bonus}
function v34BuildMeleeMultiplier(){const a=v34ActiveBuild();return 1+(a?.build?.bonus?.melee||0)}
function v34BuildIncomingMultiplier(){const a=v34ActiveBuild();return Math.max(.65,1+(a?.build?.bonus?.incoming||0))}
function v34BuildArtifactMultiplier(row){const a=v34ActiveBuild();if(!a||!row||row.path!==a.build.path)return 1;return 1+(a.build.bonus.artifact||0)+(a.mastered?.04:0)}
function v34BurnDamageMultiplier(){const a=v34ActiveBuild();return 1+(a?.build?.bonus?.burnDamage||0)}
function v34AfterPlayerSkill(id,row,effect,damage){const a=v34ActiveBuild();if(!a)return;const b=a.build.bonus||{};if(b.burn&&effect.burn)combat.burn=Math.max(combat.burn||0,(effect.burn||0)+b.burn);if(b.control&&(effect.control||effect.soulSeal||effect.domain)){if(effect.control)combat.v31Control=Math.max(combat.v31Control||0,effect.control+b.control);if(effect.soulSeal)combat.soulSeal=Math.max(combat.soulSeal||0,effect.soulSeal+b.control)}if(b.counter&&effect.counter)combat.v31Counter=Math.max(combat.v31Counter||0,effect.counter+b.counter);if(b.rage&&effect.rage)combat.v31Rage=Math.max(combat.v31Rage||0,effect.rage+b.rage);if(b.qiRestore&&damage>0&&row?.category==='drain'){const gain=Math.max(1,Math.floor(maxQi()*b.qiRestore)),before=combat.playerQi;combat.playerQi=Math.min(maxQi(),combat.playerQi+gain);combat.logs.push('【'+a.build.name+'】回补灵力 '+(combat.playerQi-before)+'。')}if(b.drain&&effect.drain&&damage>0){const gain=Math.max(1,Math.floor(damage*b.drain)),before=combat.playerHp;combat.playerHp=Math.min(maxHp(),combat.playerHp+gain);combat.logs.push('【'+a.build.name+'】额外夺取生机 '+(combat.playerHp-before)+'。')}}
function v34BuildCombatText(){const a=v34ActiveBuild();return a?'构筑：'+a.build.name+' '+a.score+'/6'+(a.mastered?' · 成型':' · 运转中'):''}
function v34InitCombat(e){ensureV34CombatShape();const m=v34EnemyMechanic(e);combat.v34EnemyMechanic=m?JSON.parse(JSON.stringify(m)):null;combat.v34PlayerDotTurns=0;combat.v34PlayerDotPct=0;combat.v34PlayerDotName='';combat.v34MechanicTriggered={};if(m)combat.logs.push('【敌方机制】'+m.name+'：'+m.desc);return m}
function v34ActionProfile(a){const s=String(a||'');if(s.startsWith('artifact:'))return {kind:'artifact',path:v32EquipmentRow(s.slice(9))?.path||'none',category:'artifact'};if(s.startsWith('skill:')){const id=s.slice(6),d=spellRegistry()[id]||{};return {kind:'skill',path:d.path||'none',category:d.category||''}}if(s==='attack')return {kind:'melee',path:state.player.daoPath,category:'melee'};return {kind:s,path:'none',category:s}}
function v34EnemyAfterPlayerAction(a,beforeHp){if(!combat)return;const m=combat.v34EnemyMechanic;if(!m)return;const profile=v34ActionProfile(a),raw=Math.max(0,beforeHp-combat.enemyHp);if(raw<=0){if(m.type==='control-resist'){combat.v31Control=Math.max(0,(combat.v31Control||0)-(m.controlReduction||0));combat.soulSeal=Math.max(0,(combat.soulSeal||0)-(m.soulSealReduction||0))}return}let reduction=0;if(m.type==='armor')reduction=m.damageReduction||0;if(m.type==='artifact-resist'&&profile.kind==='artifact')reduction=m.damageReduction||0;if(m.type==='burn-immunity'&&profile.path==='flame'){reduction=m.damageReduction||0;combat.burn=0}if(m.type==='phase'&&combat.round%(m.every||3)===0&&!v36EnemySpaceLocked())reduction=m.damageReduction||0;if(reduction>0){const blocked=Math.min(raw-1,Math.floor(raw*reduction));if(blocked>0){combat.enemyHp+=blocked;combat.logs.push('【'+m.name+'】抵消 '+blocked+' 点直接伤害。')}}if(m.type==='control-resist'){const c0=combat.v31Control||0,s0=combat.soulSeal||0;combat.v31Control=Math.max(0,c0-(m.controlReduction||0));combat.soulSeal=Math.max(0,s0-(m.soulSealReduction||0));if(c0!==combat.v31Control||s0!==combat.soulSeal)combat.logs.push('【'+m.name+'】削弱了控制与封魂效果。')}if(m.type==='reflect'||(m.type==='mirror'&&combat.round%(m.every||3)===0)){const pct=m.reflectPct||0,ref=Math.max(1,Math.floor(raw*pct));combat.playerHp=Math.max(0,combat.playerHp-ref);combat.logs.push('【'+m.name+'】反照伤害 '+ref+' 点。')}}
function v34TaxCooldowns(n=1){for(const id of state.player.activeSkillIds||[]){if(!id)continue;combat.cooldowns[id]=Math.max(Number(combat.cooldowns[id])||0,1)+n}}
function v34EnemyAttackEffect(e,raw){if(!combat)return raw;const m=combat.v34EnemyMechanic;if(!m)return raw;let dmg=raw;if(m.type==='opening-charge'&&combat.round===1)dmg=Math.ceil(dmg*(m.openingDamage||1.4));if(m.type==='berserk'&&combat.enemyHp/e.hp<=(m.threshold||.5))dmg=Math.ceil(dmg*(1+(m.mult||.4)));if(m.type==='multi-strike')dmg=Math.ceil(dmg*(1+(m.mult||.3)));if(m.type==='execute'&&combat.playerHp/maxHp()<=(m.threshold||.35))dmg=Math.ceil(dmg*(1+(m.mult||.5)));if(m.type==='qi-burn'||m.type==='soul-drain'){const loss=Math.min(combat.playerQi,Math.max(1,Math.floor(maxQi()*(m.qiDrainPct||.06))));combat.playerQi-=loss;if(loss)combat.logs.push('【'+m.name+'】抽走灵力 '+loss+'。');if(m.type==='soul-drain'&&m.healPct){const heal=Math.max(1,Math.floor(e.hp*m.healPct));combat.enemyHp=Math.min(e.hp,combat.enemyHp+heal);combat.logs.push(e.name+'借噬灵恢复 '+heal+' 气血。')}}if(m.type==='cooldown-tax'){v34TaxCooldowns(m.cooldownTax||1);combat.logs.push('【'+m.name+'】令术法运转迟滞。')}if(m.type==='domain-pressure'&&combat.round%(m.every||3)===0){v34TaxCooldowns(m.cooldownTax||1);combat.evade=0;if(combat.v31Shield>0){const cut=Math.max(1,Math.floor(combat.v31Shield*(m.shieldCut||.2)));combat.v31Shield=Math.max(0,combat.v31Shield-cut);combat.logs.push('【'+m.name+'】法域磨灭护盾 '+cut+'。')}}if(m.type==='venom'||m.type==='scorch'){combat.v34PlayerDotTurns=Math.max(combat.v34PlayerDotTurns||0,m.dotTurns||2);combat.v34PlayerDotPct=Math.max(combat.v34PlayerDotPct||0,m.dotPct||.02);combat.v34PlayerDotName=m.type==='venom'?'蚀脉毒':'灼伤';}return dmg}
function v34AfterCombatRound(){if(!combat)return;const e=combat.enemy,m=combat.v34EnemyMechanic;if((combat.v34PlayerDotTurns||0)>0){const loss=Math.max(1,Math.floor(maxHp()*(combat.v34PlayerDotPct||.02)));combat.playerHp-=loss;combat.v34PlayerDotTurns--;combat.logs.push('【'+(combat.v34PlayerDotName||'持续伤害')+'】气血 -'+loss+'。')}if(!m)return;let rate=0;if(m.type==='regeneration')rate=m.regenPct||0;if(m.type==='laststand-regen')rate=combat.enemyHp/e.hp<=(m.threshold||.4)?m.lowRegenPct||.08:m.regenPct||.03;if(rate>0&&combat.enemyHp>0){const heal=Math.max(1,Math.floor(e.hp*rate));combat.enemyHp=Math.min(e.hp,combat.enemyHp+heal);combat.logs.push('【'+m.name+'】恢复 '+heal+' 气血。')}if(m.type==='burn-immunity')combat.burn=0;}
