function v34MechanicRegistry(){const out={};for(const [name,m] of Object.entries(V34_ENEMY_MECHANICS)){const e=ENEMIES.find(x=>x.name===name);if(!e)continue;out[m.id]={...m,enemyId:e.id||ENEMY_ID_BY_NAME[name],enemyName:name}}return out}
