function v37ChooseLaw(id,force=false){ensureV37UnityShape();const p=state.player,row=V37_LAW_BY_ID[id];if(!row)return {ok:false,reason:'missing'};if(p.v37LawId&&p.v37LawId!==id)return {ok:false,reason:'fixed'};if(p.v37LawId===id)return {ok:true,reason:'known',lawId:id};if(!force){if(p.realmIndex<29)return {ok:false,reason:'realm'};if(!['法则古原','万象法坛'].includes(p.location))return {ok:false,reason:'location'};if((p.insight||0)<10||v33MaterialCount('mat-v37-law-crystal')<2||v33MaterialCount('mat-v37-rule-dust')<1)return {ok:false,reason:'cost'};p.insight-=10;v33AddMaterial('mat-v37-law-crystal',-2);v33AddMaterial('mat-v37-rule-dust',-1);advanceDays(12);if(state.flags.dead)return {ok:false,reason:'dead'}}p.v37LawId=id;p.v37LawProficiency=Math.max(5,p.v37LawProficiency||0);p.v37LawActions++;addPersonal('【法则倾向】你不再只观察散乱规则，而是正式确立【'+row.name+'】作为自身合体之路的法则倾向。','major');save();render();return {ok:true,lawId:id}}
function v37ContemplateLaw(forceGain=null){ensureV37UnityShape();const p=state.player,row=v37Law(),meta=V37_LAW_REGIONS[p.location];if(!row)return {ok:false,reason:'law'};if(!meta)return {ok:false,reason:'location'};if(p.realmIndex<29)return {ok:false,reason:'realm'};const days=meta.days;if(forceGain==null){advanceDays(days);if(state.flags.dead)return {ok:false,reason:'dead'}}const gain=forceGain==null?rint(2+meta.tier,4+meta.tier*2):Math.max(1,Number(forceGain)||1);p.v37LawProficiency=Math.min(240,(p.v37LawProficiency||0)+gain);p.v37LawActions++;let backlash=false;if(forceGain==null&&rand()<Math.max(.02,.12-meta.tier*.018)){backlash=true;p.v37LawBacklash++;p.injury=clamp((p.injury||0)+1,0,3);p.hp=Math.max(1,Math.floor(maxHp()*.55));}addPersonal('【悟法】你在'+p.location+'推演'+row.name+'，法则熟练 +'+gain+'。'+(backlash?'规则冲突反噬了经脉与元神。':''),backlash?'bad':'good');save();render();return {ok:true,gain,backlash,proficiency:p.v37LawProficiency}}
function v37IntegrateUnity(forceGain=null){ensureV37UnityShape();const p=state.player,row=v37Law();if(!row)return {ok:false,reason:'law'};if(!['天衡战城','万象法坛','归一圣墟'].includes(p.location))return {ok:false,reason:'location'};if((p.v37LawProficiency||0)<20)return {ok:false,reason:'lawProf'};const cost={'mat-v37-law-crystal':1,'mat-v37-soul-covenant-stone':1};if(forceGain==null){if(!Object.entries(cost).every(([id,n])=>v33MaterialCount(id)>=n))return {ok:false,reason:'cost'};for(const [id,n] of Object.entries(cost))v33AddMaterial(id,-n);advanceDays(8);if(state.flags.dead)return {ok:false,reason:'dead'}}const gain=forceGain==null?rint(5,10):Math.max(1,Number(forceGain)||1);p.v37Unity=Math.min(120,(p.v37Unity||0)+gain);p.v37LawActions++;addPersonal('【三元归一】你以肉身承载、元神统御、'+row.name+'定序，归一度 +'+gain+'。','major');save();render();return {ok:true,gain,unity:p.v37Unity}}
function v37CraftUnityEssence(force=false){ensureV37UnityShape();const p=state.player;if(p.location!=='归一圣墟'&&!force)return {ok:false,reason:'location'};if(p.realmIndex<29&&!force)return {ok:false,reason:'realm'};if(((p.v37LawProficiency||0)<35||(p.v37Unity||0)<30)&&!force)return {ok:false,reason:'foundation'};const cost={'mat-v37-unity-seed':2,'mat-v37-law-crystal':2,'mat-v37-soul-covenant-stone':1,'mat-v36-void-essence':1};if(!force){if(!Object.entries(cost).every(([id,n])=>v33MaterialCount(id)>=n))return {ok:false,reason:'cost'};for(const [id,n] of Object.entries(cost))v33AddMaterial(id,-n);advanceDays(8);if(state.flags.dead)return {ok:false,reason:'dead'}}v33AddMaterial('mat-v37-unity-essence',1);p.unityEssence=v33MaterialCount('mat-v37-unity-essence');addPersonal('【合体归一髓】你把空间根基、法则烙印、元神契机与肉身生机炼作一体，得到一份合体归一髓。','major');save();render();return {ok:true,count:p.unityEssence}}
function v37MajorReady(req){if(!req||req.kind!=='合体归一')return true;ensureV37UnityShape();const p=state.player;return !!p.v37LawId&&(p.v37LawProficiency||0)>=(req.lawProf||0)&&(p.v37Unity||0)>=(req.unity||0)&&v33MaterialCount('mat-v37-unity-essence')>=(req.unityEssence||0)}
function v37BreakthroughBonus(req){if(!req||req.kind!=='合体归一')return 0;const p=state.player;return Math.min(.10,Math.max(0,(p.v37LawProficiency-(req.lawProf||0))*.0015)+Math.max(0,(p.v37Unity-(req.unity||0))*.001))}
function v37MinorGate(index){ensureV37UnityShape();const p=state.player,need={30:[60,55],31:[100,75],32:[150,100]}[Number(index)];if(!need)return {ok:true};return {ok:(p.v37LawProficiency||0)>=need[0]&&(p.v37Unity||0)>=need[1],lawProf:need[0],unity:need[1]}}
function v37MinorBreakthroughDays(index){return Number(index)===30?30:Number(index)===31?45:Number(index)===32?60:null}
function v37TravelGate(route,to=null){ensureV37UnityShape();const need=Number(route?.lawProf)||0;if((state.player.v37LawProficiency||0)<need)return {ok:false,reason:'law',needLaw:need,to:to||null};return {ok:true,reason:'ok'}}
function v37AttemptUnityBreakthrough(force=null){ensureV37UnityShape();const p=state.player;if(p.realmIndex!==29)return {ok:false,reason:'realm'};if(p.progress<realm().need)return {ok:false,reason:'progress'};const req=majorBreakthroughRequirements();if(!req||req.kind!=='合体归一')return {ok:false,reason:'requirements'};if(!majorBreakthroughReady(req))return {ok:false,reason:'cost'};const chance=breakthroughChance(),old=realm().name;p.breakthroughAttempts++;p.insight-=req.insight||0;v33AddMaterial('mat-v37-unity-essence',-(req.unityEssence||0));if(force==null){advanceDays(req.days);if(state.flags.dead)return {ok:false,reason:'dead'}}const success=force==='success'?true:force==='fail'?false:rand()<chance;if(success){p.progress=0;p.realmIndex=30;p.breakthroughPity=0;p.hp=maxHp();p.qi=maxQi();const lifeGain=applyRealmLifespanMilestone();p.reputation+=520;addWorld(p.name+'完成肉身、元神与法则三元归一，领域开始反过来影响周围天地，正式踏入合体初期。','major');addPersonal('【合体】你不再只是借天地规则施法，而是让自身法则成为周围天地的一部分。'+(lifeGain?'寿元上限提升 '+lifeGain+' 年。':''),'major');save();render();return {ok:true,outcome:'success',chance,realmIndex:30}}const need=realm().need,oldProgress=p.progress;p.progress=Math.floor(need*(force==='fail'?.28:rint(20,36)/100));p.breakthroughPity=Math.min(72,(p.breakthroughPity||0)+req.pity);p.v37UnityFailures++;p.v37LawBacklash++;p.v37LawProficiency=Math.max(0,(p.v37LawProficiency||0)-5);p.v37Unity=Math.max(0,(p.v37Unity||0)-8);p.injury=3;p.hp=Math.max(1,Math.floor(maxHp()*.04));const loss=force==='fail'?Math.floor((req.lifeLoss[0]+req.lifeLoss[1])/2):rint(req.lifeLoss[0],req.lifeLoss[1]),before=p.lifespan;p.lifespan=Math.max(age()+5,p.lifespan-loss);let artifactDamaged=false;if(p.natalArtifactId&&p.equipmentInventory?.[p.natalArtifactId]&&(force==='fail'||rand()<.45)){p.equipmentInventory[p.natalArtifactId].damaged=true;artifactDamaged=true}addPersonal('【合体失败】肉身、元神与法则在归一瞬间彼此冲撞，领域雏形崩解，根基遭受重创。','bad');save();render();return {ok:true,outcome:'failure',chance,lost:Math.max(0,oldProgress-p.progress),lifeLoss:Math.max(0,before-p.lifespan),artifactDamaged,lawProf:p.v37LawProficiency,unity:p.v37Unity}}
function v37DomainReady(){const p=state.player;return p.realmIndex>=30&&!!p.v37LawId&&(p.v37LawProficiency||0)>=40}
function v37AvatarReady(){const p=state.player;return p.realmIndex>=31&&!!p.v37LawId&&(p.v37LawProficiency||0)>=90&&(p.v37Unity||0)>=65}
function v37ActivateDomain(force=false){ensureV37UnityShape();if(!combat)return false;if(!v37DomainReady())return false;if(combat.v37DomainUsed)return false;const cost=Math.max(1,Math.floor(maxQi()*.12));if(!force&&combat.playerQi<cost)return false;if(!force)combat.playerQi-=cost;combat.v37DomainUsed=true;combat.v37DomainTurns=4;combat.v37DomainLawId=state.player.v37LawId;state.player.v37DomainUses++;const law=v37Law();combat.logs.push('【领域展开】'+law.domain+'覆盖战场，周围规则开始向你的'+law.name+'倾斜。');return true}
function v37ActivateAvatar(force=false){ensureV37UnityShape();if(!combat)return false;if(!v37AvatarReady())return false;if(combat.v37AvatarUsed)return false;const cost=Math.max(1,Math.floor(maxQi()*.18));if(!force&&combat.playerQi<cost)return false;if(!force)combat.playerQi-=cost;combat.v37AvatarUsed=true;combat.v37AvatarTurns=3;state.player.v37AvatarUses++;const law=v37Law();combat.logs.push('【法相显化】'+law.avatar+'立于身后，肉身、元神与法则同时拔升。');return true}
function v37DomainActive(){return !!(combat&&(combat.v37DomainTurns||0)>0)}
function v37AvatarActive(){return !!(combat&&(combat.v37AvatarTurns||0)>0)}
function v37DamageMultiplier(def=null,effect={}){const law=v37Law();if(!law)return 1;let m=1,prof=Math.min(.16,(state.player.v37LawProficiency||0)/1200);m+=prof;if(v37LawMatch())m+=.05;if(v37DomainActive())m+=Number(law.bonus?.damage)||.08;if(v37AvatarActive())m+=.24;if(effect?.lawStrike)m+=Number(effect.lawStrike)||0;return Math.max(.8,m)}
function v37IncomingMultiplier(){const law=v37Law();let m=1;if(law?.id==='law-immovable')m+=Number(law.bonus?.incoming)||-.10;if(v37DomainActive()&&law?.id==='law-immovable')m-=.12;if(v37AvatarActive())m-=.08;if(combat?.v37LawSuppressed>0)m+=.10;return clamp(m,.48,1.35)}
function v37ArtifactMultiplier(row){const law=v37Law();if(!law||!row)return 1;return 1+(v37LawMatch()&&row.path===law.path?(law.bonus?.artifact||.06):0)+(v37DomainActive()?.05:0)+(v37AvatarActive()?.08:0)}
function v37CombatButtons(){if(!combat)return '';const d=v37DomainReady(),a=v37AvatarReady();return '<button data-combat="lawdomain" '+(!d||combat.v37DomainUsed?'disabled':'')+'>'+(d?'展开领域':'领域未成')+'</button><button data-combat="lawavatar" '+(!a||combat.v37AvatarUsed?'disabled':'')+'>'+(a?'显化法相':'法相未成')+'</button>'}
function v37CombatText(){const law=v37Law(),rows=[];if(law)rows.push(law.name+' '+state.player.v37LawProficiency);if(v37DomainActive())rows.push('领域 '+combat.v37DomainTurns);if(v37AvatarActive())rows.push('法相 '+combat.v37AvatarTurns);if(combat?.v37LawSuppressed>0)rows.push('法则受压 '+combat.v37LawSuppressed);return rows.join(' · ')}
function v37AfterCombatRound(){if(!combat)return;const law=v37Law();if(v37DomainActive()){if(law?.id==='law-annihilation'&&combat.enemyHp>0){const d=Math.max(1,Math.floor((90+state.player.realmIndex*18+(state.player.v37LawProficiency||0)*2.2)*gearSpellMultiplier()));combat.enemyHp-=d;combat.logs.push('焚灭领域持续崩解敌体，造成 '+d+' 点法则伤害。')}if(law?.id==='law-soulorder')combat.v31Control=Math.max(combat.v31Control||0,1);if(law?.id==='law-immovable'){combat.v31Shield=(combat.v31Shield||0)+Math.max(1,Math.floor(maxHp()*.025));combat.v31Counter=Math.max(combat.v31Counter||0,.18)}if(law?.id==='law-severing')combat.v31Vulnerable=Math.max(combat.v31Vulnerable||0,1);combat.v37DomainTurns--}if(v37AvatarActive())combat.v37AvatarTurns--;if((combat.v37LawSuppressed||0)>0)combat.v37LawSuppressed--;v37EnemyAfterRound()}
function v37EnemyMechanic(e){return e?.mechanic&&String(e.id||'').startsWith('enemy-v37-')?e.mechanic:null}
function v37EnemyAfterPlayerAction(a,beforeHp){if(!combat)return;const m=v37EnemyMechanic(combat.enemy);if(!m)return;const raw=Math.max(0,beforeHp-combat.enemyHp);if(raw<=0)return;if(m.type==='domain-armor'&&!v37DomainActive()){const blocked=Math.min(raw-1,Math.floor(raw*(m.reduction||.3)));if(blocked>0){combat.enemyHp+=blocked;combat.logs.push('【'+m.name+'】在你未展开领域时抵消 '+blocked+' 点伤害。')}}if(m.type==='remnant-avatar'&&combat.enemyHp/combat.enemy.hp<=(m.threshold||.4)){const blocked=Math.min(raw-1,Math.floor(raw*(m.reduction||.18)));if(blocked>0)combat.enemyHp+=blocked}}
function v37EnemyAttackEffect(e,dmg){if(!combat)return dmg;const m=v37EnemyMechanic(e);if(!m)return dmg;if(['law-cut','domain-break','war-pressure','sovereign-domain','law-shift'].includes(m.type)&&v37DomainActive()){combat.v37DomainTurns=Math.max(0,combat.v37DomainTurns-(m.domainCut||1));combat.logs.push('【'+m.name+'】撕裂你的领域边界。')}if(m.type==='avatar-hunt'&&v37AvatarActive())dmg=Math.ceil(dmg*(1+(m.mult||.4)));if(m.type==='unity-drain'){const q=Math.min(combat.playerQi,Math.max(1,Math.floor(maxQi()*(m.qiDrainPct||.06))));combat.playerQi-=q;if(v37AvatarActive())combat.v37AvatarTurns=Math.max(0,combat.v37AvatarTurns-(m.avatarCut||1));}if(m.type==='lawstorm'&&combat.round%(m.every||3)===0)dmg=Math.ceil(dmg*(1+(m.mult||.3)));if(m.type==='law-seal')combat.v37LawSuppressed=Math.max(combat.v37LawSuppressed||0,m.turns||2);if(m.type==='sovereign-domain'){if(combat.v31Shield>0)combat.v31Shield=Math.max(0,Math.floor(combat.v31Shield*(1-(m.shieldCut||.1))));combat.v31Control=Math.max(0,(combat.v31Control||0)-(m.controlReduction||0))}if(m.type==='remnant-avatar'&&combat.enemyHp/e.hp<=(m.threshold||.4))dmg=Math.ceil(dmg*(1+(m.mult||.5)));return dmg}
function v37EnemyAfterRound(){if(!combat)return;const m=v37EnemyMechanic(combat.enemy);if(!m)return;if(m.type==='law-mirror'&&combat.round%(m.every||3)===0&&v37DomainActive()){const d=Math.max(1,Math.floor(maxHp()*(m.mult||.02)*.08));combat.playerHp=Math.max(0,combat.playerHp-d);combat.logs.push('【'+m.name+'】镜映领域，反压气血 '+d+'。')}if(m.type==='law-shift'&&v37DomainActive()&&combat.round%2===0)combat.v37DomainTurns=Math.max(0,combat.v37DomainTurns-1)}
function v37WarCycle(){return Math.max(0,Math.floor((dayNumber()-1)/120))}
function v37RefreshWarState(){if(!state?.world)return;const w=state.world,cycle=v37WarCycle(),phase=(dayNumber()-1)%120;if(w.v37WarCycle!==cycle){w.v37WarCycle=cycle;w.v37WarScore=0;w.v37EnemyScore=0;w.v37LastWarResult='none'}if(w.v37WarStatus!=='forced')w.v37WarStatus=phase>=60&&phase<90?'active':'peace';if(w.v37WarStatus==='active'&&w.v37WarUntil<dayNumber())w.v37WarUntil=dayNumber()+(90-phase)}
function v37StartHighWar(force=true){ensureV37UnityShape();const w=state.world;w.v37WarStatus=force?'forced':'active';w.v37WarUntil=dayNumber()+30;w.v37WarScore=0;w.v37EnemyScore=0;w.v37WarEvents++;addWorld('【天衡大战】裂界高阶修士冲击天衡战城，领域与法相开始在整片地域正面碰撞。','major');return v37WarSnapshot()}
function v37WarActive(){ensureV37UnityShape();return state.world.v37WarStatus==='active'||state.world.v37WarStatus==='forced'}
function v37JoinWarFront(id,forceOutcome=null){ensureV37UnityShape();const front=V37_WAR_FRONT_BY_ID[id],p=state.player;if(!front)return {ok:false,reason:'missing'};if(!v37WarActive()&&forceOutcome==null)return {ok:false,reason:'inactive'};if(p.realmIndex<29&&forceOutcome==null)return {ok:false,reason:'realm'};if(p.location!==front.region&&forceOutcome==null)return {ok:false,reason:'location'};if(forceOutcome){return v37ResolveWarResult(front.id,forceOutcome==='win')}const enemy=ENEMIES.find(e=>e.id===front.enemyId);if(!enemy)return {ok:false,reason:'enemy'};startCombat(enemy);if(combat)combat.v37WarFrontId=front.id;return {ok:true,combat:true,frontId:front.id}}
function v37ResolveWarResult(frontId,win){ensureV37UnityShape();const w=state.world,p=state.player;if(win){w.v37WarScore++;p.v37HighWarWins++;p.reputation+=18;v33AddMaterial('mat-v37-war-seal',1)}else w.v37EnemyScore++;if(w.v37WarScore>=3){w.v37WarStatus='peace';w.v37LastWarResult='victory';addWorld('【天衡大捷】三处关键战线被稳住，天渊边荒重新夺回规则主导权。','major')}else if(w.v37EnemyScore>=3){w.v37WarStatus='peace';w.v37LastWarResult='defeat';addWorld('【天衡失守】高阶战线被撕开，边荒规则短期陷入混乱。','bad')}return {ok:true,win,score:w.v37WarScore,enemyScore:w.v37EnemyScore,status:w.v37WarStatus}}
function onV37CombatWin(e){ensureV37UnityShape();const p=state.player;if(combat?.v37WarFrontId)v37ResolveWarResult(combat.v37WarFrontId,true);else if(String(e?.id||'').startsWith('enemy-v37-')&&p.battleWins%3===0)p.v37LawProficiency=Math.min(240,(p.v37LawProficiency||0)+1)}
function v37WarSnapshot(){ensureV37UnityShape();const w=state.world;return {cycle:w.v37WarCycle,status:w.v37WarStatus,score:w.v37WarScore,enemyScore:w.v37EnemyScore,until:w.v37WarUntil,lastResult:w.v37LastWarResult,fronts:JSON.parse(JSON.stringify(V37_WAR_FRONTS))}}
function v37CatalogSnapshot(){return {realms:REALMS.length,regions:Object.keys(LOCATIONS).length,routes:TRAVEL_ROUTES.length,materials:V33_MATERIAL_CATALOG.length,recipes:V33_RECIPE_CATALOG.length,manuals:V31_MANUAL_CATALOG.length,spells:V31_SPELL_CATALOG.length,equipment:V32_EQUIPMENT_CATALOG.length,artifacts:V32_EQUIPMENT_CATALOG.filter(x=>x.trueArtifact).length,enemies:ENEMIES.length,laws:V37_LAWS.length,warFronts:V37_WAR_FRONTS.length}}
function v37StateSnapshot(){ensureV37UnityShape();const p=state.player;return {lawId:p.v37LawId,lawProficiency:p.v37LawProficiency,unity:p.v37Unity,lawBacklash:p.v37LawBacklash,unityFailures:p.v37UnityFailures,domainUses:p.v37DomainUses,avatarUses:p.v37AvatarUses,warWins:p.v37HighWarWins,unityEssence:v33MaterialCount('mat-v37-unity-essence'),war:v37WarSnapshot()}}
function v37SetPlayerForTest({realmIndex=null,location=null,lawId=null,lawProficiency=null,unity=null,unityEssence=null,spaceInsight=null,insight=null,progressFull=false,stones=null}={}){ensureV37UnityShape();const p=state.player;if(realmIndex!=null)p.realmIndex=clamp(Number(realmIndex)||0,0,REALMS.length-1);if(location)p.location=location;if(lawId!==null)p.v37LawId=lawId;if(lawProficiency!=null)p.v37LawProficiency=Math.max(0,Number(lawProficiency)||0);if(unity!=null)p.v37Unity=Math.max(0,Number(unity)||0);if(unityEssence!=null){p.unityEssence=Math.max(0,Number(unityEssence)||0);p.materialInventoryById['mat-v37-unity-essence']=p.unityEssence}if(spaceInsight!=null)p.v36SpaceInsight=Math.max(0,Number(spaceInsight)||0);if(insight!=null)p.insight=Math.max(0,Number(insight)||0);if(stones!=null)p.spiritStones=Math.max(0,Number(stones)||0);if(progressFull)p.progress=realm().need;p.hp=maxHp();p.qi=maxQi();syncV33AlchemyState();return true}
function renderV37UnityPanel(){let panel=$('v37UnityPanel');if(!panel){const page=$('page-character');if(!page)return;panel=document.createElement('section');panel.className='panel';panel.id='v37UnityPanel';panel.innerHTML='<h2>合体 · 法则与三元归一</h2><p class="section-tip">炼虚解决空间坐标，合体解决“你自身能否成为一套稳定规则”。必须确立法则倾向，让肉身、元神与法则逐步归一，并在高阶战争中真正使用领域与法相。</p><div id="v37UnityInfo"></div><div id="v37UnityActions"></div>';page.appendChild(panel)}ensureV37UnityShape();const p=state.player,law=v37Law(),info=$('v37UnityInfo'),actions=$('v37UnityActions');if(!info||!actions)return;info.innerHTML='<div class="kv"><span>法则倾向</span><b>'+esc(law?.name||'尚未确立')+'</b></div><div class="kv"><span>法则熟练</span><b>'+p.v37LawProficiency+' / 240</b></div><div class="kv"><span>三元归一度</span><b>'+p.v37Unity+' / 120</b></div><div class="kv"><span>合体归一髓</span><b>'+v33MaterialCount('mat-v37-unity-essence')+'</b></div><div class="kv"><span>领域 / 法相</span><b>'+(v37DomainReady()?'已可展开':'未成')+' / '+(v37AvatarReady()?'已可显化':'未成')+'</b></div>';let html='';if(!law&&p.realmIndex>=29)html='<h3>确立法则倾向</h3>'+V37_LAWS.map(x=>'<div class="skill-card"><div class="skill-head"><b>'+esc(x.name)+'</b><span>'+esc(DAO_PATHS[x.path]?.name||x.path)+'</span></div><div class="skill-desc">'+esc(x.desc)+'</div><div class="event-actions"><button data-v37-law="'+x.id+'">确立倾向</button></div></div>').join('');if(law){const meta=V37_LAW_REGIONS[p.location];if(meta)html+='<div class="event-actions"><button data-v37-contemplate>悟法 · '+meta.days+'日</button><button data-v37-unity>三元归一 · 8日</button>'+(p.location==='归一圣墟'?'<button data-v37-essence>凝炼合体归一髓 · 8日</button>':'')+'</div>';html+='<div class="section-tip">领域：'+esc(law.domain)+' · 法相：'+esc(law.avatar)+'。领域需合体初期且法则熟练40；法相需合体中期、法则熟练90、归一度65。</div>'}const war=v37WarSnapshot();html+='<h3>天衡高阶战线</h3><div class="section-tip">状态：'+esc(war.status)+' · 我方 '+war.score+' / 敌方 '+war.enemyScore+'。高阶战争以领域与法相争夺整片地域，不再只是普通随机遭遇。</div>';if(v37WarActive())for(const f of V37_WAR_FRONTS)html+='<div class="skill-card"><b>'+esc(f.name)+'</b><div class="skill-desc">'+esc(f.desc)+' · 地点：'+esc(f.region)+'</div><div class="event-actions"><button data-v37-front="'+f.id+'" '+(p.location===f.region?'':'disabled')+'>加入战线</button></div></div>';actions.innerHTML=html;actions.querySelectorAll('[data-v37-law]').forEach(b=>b.onclick=()=>v37ChooseLaw(b.dataset.v37Law));const c=actions.querySelector('[data-v37-contemplate]');if(c)c.onclick=()=>v37ContemplateLaw();const u=actions.querySelector('[data-v37-unity]');if(u)u.onclick=()=>v37IntegrateUnity();const e=actions.querySelector('[data-v37-essence]');if(e)e.onclick=()=>v37CraftUnityEssence();actions.querySelectorAll('[data-v37-front]').forEach(b=>b.onclick=()=>v37JoinWarFront(b.dataset.v37Front))}
function v37AfterLawSkill(id,row,effect,damage){if(!combat)return;if(effect?.lawDomain&&v37DomainReady()){combat.v37DomainUsed=true;combat.v37DomainTurns=Math.max(combat.v37DomainTurns||0,Number(effect.lawDomain)+2);combat.v37DomainLawId=state.player.v37LawId}if(effect?.avatarEcho&&v37AvatarReady()){combat.v37AvatarUsed=true;combat.v37AvatarTurns=Math.max(combat.v37AvatarTurns||0,2)}if(effect?.lawStrike)state.player.v37LawProficiency=Math.min(240,(state.player.v37LawProficiency||0)+(damage>0?.15:0));}

