function v38ContemplateOrigin(forceGain=null){ensureV38MahayanaShape();const p=state.player,meta=v38OriginRegion();if(!meta)return {ok:false,reason:'location'};if(p.realmIndex<33)return {ok:false,reason:'realm'};if((p.v37LawProficiency||0)<160||(p.v37Unity||0)<100)return {ok:false,reason:'foundation'};if(forceGain==null){advanceDays(meta.days);if(state.flags.dead)return {ok:false,reason:'dead'}}let gain=forceGain==null?rint(3+meta.tier,6+meta.tier*2):Math.max(1,Number(forceGain)||1);if(forceGain==null)gain=Math.max(1,Math.round(gain*v38WorldOrderMultiplier()));let backlash=false;if(forceGain==null&&rand()<Math.max(.025,.14-meta.tier*.022)){backlash=true;p.v38OriginBacklash++;p.injury=clamp((p.injury||0)+1,0,3);p.hp=Math.max(1,Math.floor(maxHp()*.48));gain=Math.max(1,Math.floor(gain*.55))}p.v38OriginInsight=Math.min(360,(p.v38OriginInsight||0)+gain);p.v38OriginActions++;addPersonal('【天地本源】你在'+p.location+'感应人界根本脉动，本源领悟 +'+gain+'。'+(backlash?'世界本源反压肉身与元神，造成反噬。':''),backlash?'bad':'major');save();render();return {ok:true,gain,backlash,origin:p.v38OriginInsight}}
function v38ExerciseWorldAuthority(forceGain=null){ensureV38MahayanaShape();const p=state.player;if(p.location!=='人界议庭'&&forceGain==null)return {ok:false,reason:'location'};if(p.realmIndex<34)return {ok:false,reason:'realm'};if((p.v38OriginInsight||0)<25)return {ok:false,reason:'origin'};if(forceGain==null){advanceDays(10);if(state.flags.dead)return {ok:false,reason:'dead'}}const gain=forceGain==null?rint(4,8):Math.max(1,Number(forceGain)||1);p.v38WorldAuthority=Math.min(240,(p.v38WorldAuthority||0)+gain);p.v38OriginActions++;if(p.sect&&p.sect!=='散修')p.sectPrestige=(p.sectPrestige||0)+Math.max(1,Math.floor(gain/2));addPersonal('【世界权柄】你在人界议庭处理祖脉与大域事务，世界权柄 +'+gain+'。','major');save();render();return {ok:true,gain,authority:p.v38WorldAuthority}}
function v38CraftMahayanaEssence(force=false){ensureV38MahayanaShape();const p=state.player;if(!['界源海','天穹祖脉'].includes(p.location)&&!force)return {ok:false,reason:'location'};if(p.realmIndex<33&&!force)return {ok:false,reason:'realm'};if(((p.v38OriginInsight||0)<35||(p.v38WorldAuthority||0)<10)&&!force)return {ok:false,reason:'foundation'};const cost={'mat-v38-origin-crystal':2,'mat-v38-heaven-vein-marrow':1,'mat-v38-world-essence-dew':1,'mat-v37-unity-essence':1};if(!force){if(!Object.entries(cost).every(([id,n])=>v33MaterialCount(id)>=n))return {ok:false,reason:'cost'};for(const [id,n] of Object.entries(cost))v33AddMaterial(id,-n);advanceDays(12);if(state.flags.dead)return {ok:false,reason:'dead'}}v33AddMaterial('mat-v38-mahayana-essence',1);p.mahayanaEssence=v33MaterialCount('mat-v38-mahayana-essence');addPersonal('【大乘本源髓】你把合体归一根基与人界本源炼成一体，得到一份大乘本源髓。','major');save();render();return {ok:true,count:p.mahayanaEssence}}
function v38TemperNatalOrigin(force=false){ensureV38MahayanaShape();const p=state.player,id=p.natalArtifactId,inv=id&&p.equipmentInventory?.[id];if(!inv)return {ok:false,reason:'natal'};if(!['天穹祖脉','九霄劫台'].includes(p.location)&&!force)return {ok:false,reason:'location'};if(p.realmIndex<34&&!force)return {ok:false,reason:'realm'};if((inv.originMarks||0)>=9)return {ok:false,reason:'max'};const cost={'mat-v38-natal-source-crystal':1,'mat-v38-origin-crystal':1,'mat-v38-origin-gold':1};if(!force){if(!Object.entries(cost).every(([mid,n])=>v33MaterialCount(mid)>=n))return {ok:false,reason:'cost'};for(const [mid,n] of Object.entries(cost))v33AddMaterial(mid,-n);advanceDays(14);if(state.flags.dead)return {ok:false,reason:'dead'}}inv.originMarks=Math.min(9,(Number(inv.originMarks)||0)+1);inv.warmth=Math.min(1000,(Number(inv.warmth)||0)+80);p.v38NatalOriginMarks=inv.originMarks;addPersonal('【本命融源】你的本命法宝承下一道界源烙印（'+inv.originMarks+'/9），开始从个人法宝向渡劫根基蜕变。','major');save();render();return {ok:true,marks:inv.originMarks,artifactId:id}}
