function v38PrepareTribulation(kind,force=false){ensureV38MahayanaShape();const p=state.player;if(!V38_TRIB_PREP_KEYS.includes(kind))return {ok:false,reason:'kind'};if(!v38TribulationPrepUnlocked()&&!force)return {ok:false,reason:'realm'};if(p.location!=='九霄劫台'&&!force)return {ok:false,reason:'location'};const costs={body:{'mat-v38-tribulation-stone':1,'mat-v38-heaven-vein-marrow':1},soul:{'mat-v38-soulstar-dew':1,'mat-v38-tribulation-stone':1},law:{'mat-v38-origin-crystal':1,'mat-v38-immortal-mortal-dust':1},artifact:{'mat-v38-natal-source-crystal':1,'mat-v38-tribulation-stone':1},formation:{'mat-v38-tribulation-array-core':1,'mat-v38-origin-gold':1}};if(kind==='artifact'&&(p.v38NatalOriginMarks||0)<2&&!force)return {ok:false,reason:'natal'};if(!force){if(!Object.entries(costs[kind]).every(([id,n])=>v33MaterialCount(id)>=n))return {ok:false,reason:'cost'};for(const [id,n] of Object.entries(costs[kind]))v33AddMaterial(id,-n);advanceDays(12);if(state.flags.dead)return {ok:false,reason:'dead'}}const gain=force?12:rint(8,14);p.v38TribulationPrep[kind]=Math.min(100,(p.v38TribulationPrep[kind]||0)+gain);addPersonal('【渡劫准备】'+({body:'肉身',soul:'元神',law:'法则',artifact:'本命法宝',formation:'阵法'}[kind])+'准备度 +'+gain+'。这只是劫前准备，真正渡劫将在下一阶段开启。','major');save();render();return {ok:true,kind,gain,value:p.v38TribulationPrep[kind]}}
