function v38MajorReady(req){if(!req||req.kind!=='大乘证道')return true;ensureV38MahayanaShape();const p=state.player;return (p.v37LawProficiency||0)>=(req.lawProf||0)&&(p.v37Unity||0)>=(req.unity||0)&&(p.v38OriginInsight||0)>=(req.origin||0)&&(p.v38WorldAuthority||0)>=(req.authority||0)&&(p.v38NatalOriginMarks||0)>=(req.natalMarks||0)&&v33MaterialCount('mat-v38-mahayana-essence')>=(req.mahayanaEssence||0)}
function v38BreakthroughBonus(req){if(!req||req.kind!=='大乘证道')return 0;const p=state.player;return Math.min(.08,Math.max(0,(p.v38OriginInsight-(req.origin||0))*.0009)+Math.max(0,(p.v38WorldAuthority-(req.authority||0))*.0007)+(p.v38NatalOriginMarks||0)*.003)}
function v38MinorGate(index){ensureV38MahayanaShape();const p=state.player,need={34:[80,40,2],35:[145,85,4],36:[230,140,6]}[Number(index)];if(!need)return {ok:true};return {ok:(p.v38OriginInsight||0)>=need[0]&&(p.v38WorldAuthority||0)>=need[1]&&(p.v38NatalOriginMarks||0)>=need[2],origin:need[0],authority:need[1],natalMarks:need[2]}}
function v38MinorBreakthroughDays(index){return Number(index)===34?75:Number(index)===35?105:Number(index)===36?150:null}
function v38TravelGate(route,to=null){ensureV38MahayanaShape();const need=Number(route?.originInsight)||0;if((state.player.v38OriginInsight||0)<need)return {ok:false,reason:'origin',needOrigin:need,to:to||null};return {ok:true,reason:'ok'}}
function v38AttemptMahayanaBreakthrough(force=null){ensureV38MahayanaShape();const p=state.player;if(p.realmIndex!==33)return {ok:false,reason:'realm'};if(p.progress<realm().need)return {ok:false,reason:'progress'};const req=majorBreakthroughRequirements();if(!req||req.kind!=='大乘证道')return {ok:false,reason:'requirements'};if(!majorBreakthroughReady(req))return {ok:false,reason:'cost'};const chance=breakthroughChance();p.breakthroughAttempts++;p.insight-=req.insight||0;v33AddMaterial('mat-v38-mahayana-essence',-(req.mahayanaEssence||0));if(force==null){advanceDays(req.days);if(state.flags.dead)return {ok:false,reason:'dead'}}const success=force==='success'?true:force==='fail'?false:rand()<chance;if(success){p.progress=0;p.realmIndex=34;p.breakthroughPity=0;p.hp=maxHp();p.qi=maxQi();const lifeGain=applyRealmLifespanMilestone();p.reputation+=900;p.v38WorldAuthority=Math.max(25,p.v38WorldAuthority||0);state.world.v38WorldOrder=clamp((state.world.v38WorldOrder||55)+4,0,100);addWorld(p.name+'以自身法则接入人界本源，世界诸宗正式承认其为大乘修士。','major');addPersonal('【大乘】你已不是单纯借用天地，而是能以自身存在影响一域规则与世界秩序。'+(lifeGain?'寿元上限提升 '+lifeGain+' 年。':''),'major');save();render();return {ok:true,outcome:'success',chance,realmIndex:34}}const need=realm().need,oldProgress=p.progress;p.progress=Math.floor(need*(force==='fail'?.20:rint(14,28)/100));p.breakthroughPity=Math.min(78,(p.breakthroughPity||0)+req.pity);p.v38MahayanaFailures++;p.v38OriginBacklash++;p.v37LawProficiency=Math.max(0,(p.v37LawProficiency||0)-10);p.v37Unity=Math.max(0,(p.v37Unity||0)-12);p.v38OriginInsight=Math.max(0,(p.v38OriginInsight||0)-8);p.v38WorldAuthority=Math.max(0,(p.v38WorldAuthority||0)-5);p.injury=3;p.hp=Math.max(1,Math.floor(maxHp()*.025));const loss=force==='fail'?Math.floor((req.lifeLoss[0]+req.lifeLoss[1])/2):rint(req.lifeLoss[0],req.lifeLoss[1]),before=p.lifespan;p.lifespan=Math.max(age()+5,p.lifespan-loss);let artifactDamaged=false;const inv=p.natalArtifactId&&p.equipmentInventory?.[p.natalArtifactId];if(inv&&(force==='fail'||rand()<.60)){inv.damaged=true;inv.originMarks=Math.max(0,(Number(inv.originMarks)||0)-1);p.v38NatalOriginMarks=inv.originMarks;artifactDamaged=true}state.world.v38WorldOrder=clamp((state.world.v38WorldOrder||55)-3,0,100);addPersonal('【大乘失败】自身法则试图接入人界本源时遭到世界反压，三元归一、法则与本命法宝同时震荡。','bad');save();render();return {ok:true,outcome:'failure',chance,lost:Math.max(0,oldProgress-p.progress),lifeLoss:Math.max(0,before-p.lifespan),artifactDamaged,origin:p.v38OriginInsight,authority:p.v38WorldAuthority}}
function v38StartWorldCrisis(forceId=null){ensureV38MahayanaShape();const p=state.player,w=state.world;if(p.realmIndex<34)return {ok:false,reason:'realm'};if(w.v38CrisisStatus==='active')return {ok:false,reason:'active',crisisId:w.v38ActiveCrisisId};const row=forceId?V38_CRISIS_BY_ID[forceId]:V38_WORLD_CRISES[(Math.floor(dayNumber()/30)+w.v38CrisisEvents)%V38_WORLD_CRISES.length];if(!row)return {ok:false,reason:'missing'};w.v38CrisisStatus='active';w.v38ActiveCrisisId=row.id;w.v38CrisisEvents++;w.v38CrisisCycle=Math.floor(dayNumber()/30);w.v38WorldOrder=clamp((w.v38WorldOrder||55)-Math.ceil(row.orderLoss*.35),0,100);addWorld('【世界危机】'+row.name+'爆发于'+row.region+'：'+row.desc,'bad');save();render();return {ok:true,crisisId:row.id,region:row.region,enemyId:row.enemyId}}
function v38ResolveWorldCrisis(id,win){ensureV38MahayanaShape();const p=state.player,w=state.world,row=V38_CRISIS_BY_ID[id];if(!row)return {ok:false,reason:'missing'};if(win){w.v38WorldOrder=clamp((w.v38WorldOrder||55)+row.orderLoss,0,100);p.v38WorldAuthority=Math.min(240,(p.v38WorldAuthority||0)+row.rewardAuthority);p.v38OriginInsight=Math.min(360,(p.v38OriginInsight||0)+row.rewardOrigin);p.v38WorldCrisisWins++;w.v38PowerStanding[row.powerId]=clamp((w.v38PowerStanding[row.powerId]||0)+12,-100,100);if(p.sect&&p.sect!=='散修'){p.sectContribution=(p.sectContribution||0)+35;p.sectPrestige=(p.sectPrestige||0)+12}w.v38LastCrisisResult='victory';v35ApplyWarShock('relief');addWorld('【大乘定世】'+p.name+'平定'+row.name+'，'+row.region+'与相关宗门的秩序得到实际恢复。','major')}else{w.v38WorldOrder=clamp((w.v38WorldOrder||55)-row.orderLoss,0,100);p.v38WorldAuthority=Math.max(0,(p.v38WorldAuthority||0)-4);w.v38PowerStanding[row.powerId]=clamp((w.v38PowerStanding[row.powerId]||0)-6,-100,100);w.v38LastCrisisResult='failure';v35ApplyWarShock('shortage');addWorld('【世界失衡】'+row.name+'未能平定，人界秩序与高阶商路进一步恶化。','bad')}w.v38CrisisStatus='peace';w.v38ActiveCrisisId=null;save();render();return {ok:true,win:!!win,worldOrder:w.v38WorldOrder,authority:p.v38WorldAuthority}}
function v38JoinWorldCrisis(id,outcome=null){ensureV38MahayanaShape();const w=state.world,row=V38_CRISIS_BY_ID[id||w.v38ActiveCrisisId];if(!row)return {ok:false,reason:'missing'};if(w.v38CrisisStatus!=='active'||w.v38ActiveCrisisId!==row.id)return {ok:false,reason:'inactive'};if(state.player.location!==row.region&&outcome==null)return {ok:false,reason:'location'};if(outcome==='win'||outcome==='loss')return v38ResolveWorldCrisis(row.id,outcome==='win');startCombat(row.enemyId);if(combat)combat.v38CrisisId=row.id;return {ok:!!combat,crisisId:row.id}}
function v38WorldSnapshot(){ensureV38MahayanaShape();const w=state.world,p=state.player;return {worldOrder:w.v38WorldOrder,crisisStatus:w.v38CrisisStatus,activeCrisisId:w.v38ActiveCrisisId,lastResult:w.v38LastCrisisResult,powerStanding:{...w.v38PowerStanding},authority:p.v38WorldAuthority,crisisWins:p.v38WorldCrisisWins}}
function v38WorldEdictReady(){const p=state.player;return p.realmIndex>=34&&(p.v38OriginInsight||0)>=40&&(p.v38WorldAuthority||0)>=20}
function v38ActivateWorldEdict(force=false){ensureV38MahayanaShape();if(!combat||!v38WorldEdictReady()||combat.v38WorldEdictUsed)return false;const cost=Math.max(1,Math.floor(maxQi()*.20));if(!force&&combat.playerQi<cost)return false;if(!force)combat.playerQi-=cost;combat.v38WorldEdictUsed=true;combat.v38WorldEdictTurns=3;state.player.v38WorldEdictUses++;combat.logs.push('【世界敕令】你以大乘权柄借来一缕人界本源，领域、法相与本命法宝同时得到世界加持。');return true}
function v38WorldEdictActive(){return !!(combat&&(combat.v38WorldEdictTurns||0)>0)}
function v38DamageMultiplier(effect={}){ensureV38MahayanaShape();let m=1+Math.min(.18,(state.player.v38OriginInsight||0)/1800);if(v38WorldEdictActive())m+=.28;if(effect?.originStrike)m+=Number(effect.originStrike)||0;if(combat?.v38AuthoritySuppressed>0)m-=.10;return Math.max(.72,m)}
function v38IncomingMultiplier(){let m=1;if(v38WorldEdictActive())m-=.16;if(combat?.v38OriginGuard>0)m-=.18;if(combat?.v38AuthoritySuppressed>0)m+=.10;return clamp(m,.42,1.40)}
function v38ArtifactMultiplier(row){ensureV38MahayanaShape();let m=1;const marks=state.player.v38NatalOriginMarks||0;if(row?.artifactId&&row.artifactId===state.player.natalArtifactId)m+=marks*.035;if(v38WorldEdictActive())m+=.10;if(combat?.v38NatalSuppressed>0&&row?.artifactId===state.player.natalArtifactId)m-=.20;return Math.max(.65,m)}
function v38CombatButtons(){if(!combat)return '';const ready=v38WorldEdictReady();return '<button data-combat="worldedict" '+(!ready||combat.v38WorldEdictUsed?'disabled':'')+'>'+(ready?'世界敕令':'权柄未成')+'</button>'}
function v38CombatText(){if(!state)return '';const rows=[];if(state.player.realmIndex>=33)rows.push('本源 '+(state.player.v38OriginInsight||0));if(state.player.realmIndex>=34)rows.push('权柄 '+(state.player.v38WorldAuthority||0));if(v38WorldEdictActive())rows.push('敕令 '+combat.v38WorldEdictTurns);if(combat?.v38AuthoritySuppressed>0)rows.push('权柄受压 '+combat.v38AuthoritySuppressed);if(combat?.v38NatalSuppressed>0)rows.push('本命受压 '+combat.v38NatalSuppressed);return rows.join(' · ')}
function v38AfterOriginSkill(id,row,effect,damage){if(!combat||!effect)return;if(effect.worldEdict&&v38WorldEdictReady()){combat.v38WorldEdictUsed=true;combat.v38WorldEdictTurns=Math.max(combat.v38WorldEdictTurns||0,Number(effect.worldEdict)||2)}if(effect.originGuard)combat.v38OriginGuard=Math.max(combat.v38OriginGuard||0,Number(effect.originGuard)||1);if(effect.originStrike&&damage>0)state.player.v38OriginInsight=Math.min(360,(state.player.v38OriginInsight||0)+.12)}
function v38EnemyMechanic(e){return e?.mechanic&&String(e.id||'').startsWith('enemy-v38-')?e.mechanic:null}
function v38EnemyAfterPlayerAction(a,beforeHp){if(!combat)return;const m=v38EnemyMechanic(combat.enemy);if(!m)return;const raw=Math.max(0,beforeHp-combat.enemyHp);if(raw<=0)return;if(m.type==='source-armor'&&!v38WorldEdictActive()){const blocked=Math.min(raw-1,Math.floor(raw*(m.reduction||.3)));if(blocked>0){combat.enemyHp+=blocked;combat.logs.push('【'+m.name+'】抵消 '+blocked+' 点未获世界权柄加持的伤害。')}}if(m.type==='origin-mirror'&&v38WorldEdictActive()&&combat.round%(m.every||3)===0){const reflected=Math.max(1,Math.floor(raw*(m.mult||.15)));combat.playerHp=Math.max(1,combat.playerHp-reflected);combat.logs.push('【'+m.name+'】反照本源威压，你受到 '+reflected+' 点反震。')}}
function v38EnemyAttackEffect(e,dmg){if(!combat)return dmg;const m=v38EnemyMechanic(e);if(!m)return dmg;if(['origin-erosion','order-drain','sovereign'].includes(m.type)&&v38WorldEdictActive())combat.v38WorldEdictTurns=Math.max(0,combat.v38WorldEdictTurns-(m.edictCut||1));if(m.type==='world-crush'&&!v38WorldEdictActive())dmg=Math.ceil(dmg*(1+(m.mult||.3)));if(m.type==='order-drain'&&combat.v31Shield>0)combat.v31Shield=Math.max(0,Math.floor(combat.v31Shield*(1-(m.shieldCut||.12))));if(m.type==='authority-seal'||m.type==='worldlaw-seal')combat.v38AuthoritySuppressed=Math.max(combat.v38AuthoritySuppressed||0,m.turns||2);if(m.type==='natal-break'&&combat.round%(m.every||3)===0)combat.v38NatalSuppressed=Math.max(combat.v38NatalSuppressed||0,m.turns||2);if(m.type==='tribulation-echo'&&combat.round%(m.every||3)===0)dmg=Math.ceil(dmg*(1+(m.mult||.4)));if(m.type==='world-beast'&&combat.enemyHp/e.hp<=(m.threshold||.45))dmg=Math.ceil(dmg*(1+(m.mult||.5)));if(m.type==='sovereign'){if(v37DomainActive())combat.v37DomainTurns=Math.max(0,combat.v37DomainTurns-(m.domainCut||1));if(v37AvatarActive())combat.v37AvatarTurns=Math.max(0,combat.v37AvatarTurns-(m.avatarCut||1))}if(m.type==='keeper'){const prep=v38TribulationPrepSnapshot();if(prep.total<120)dmg=Math.ceil(dmg*(1+(m.mult||.4)))}return dmg}
function v38AfterCombatRound(){if(!combat)return;if((combat.v38WorldEdictTurns||0)>0)combat.v38WorldEdictTurns--;if((combat.v38OriginGuard||0)>0)combat.v38OriginGuard--;if((combat.v38AuthoritySuppressed||0)>0)combat.v38AuthoritySuppressed--;if((combat.v38NatalSuppressed||0)>0)combat.v38NatalSuppressed--}
function onV38CombatWin(e){ensureV38MahayanaShape();if(combat?.v38CrisisId)return v38ResolveWorldCrisis(combat.v38CrisisId,true);if(!e||e.nonLethal||!String(e.id||'').startsWith('enemy-v38-'))return null;const p=state.player;p.v38WorldCrisisWins+=0;let gain=0;if(p.battleWins%3===0){gain=1;p.v38OriginInsight=Math.min(360,(p.v38OriginInsight||0)+1);addPersonal('【本源实战】与世界级异灵交锋后，你对天地本源的运转多了一分理解。','major')}return {originGain:gain}}
function v38CatalogSnapshot(){return {realms:REALMS.length,regions:Object.keys(LOCATIONS).length,routes:TRAVEL_ROUTES.length,materials:V33_MATERIAL_CATALOG.length,recipes:V33_RECIPE_CATALOG.length,manuals:V31_MANUAL_CATALOG.length,spells:V31_SPELL_CATALOG.length,equipment:V32_EQUIPMENT_CATALOG.length,artifacts:V32_EQUIPMENT_CATALOG.filter(x=>x.trueArtifact).length,enemies:ENEMIES.length,auctionPool:V35_AUCTION_POOL.length,worldPowers:V38_WORLD_POWERS.length,crises:V38_WORLD_CRISES.length}}
function v38StateSnapshot(){ensureV38MahayanaShape();const p=state.player;return {originInsight:p.v38OriginInsight,worldAuthority:p.v38WorldAuthority,originBacklash:p.v38OriginBacklash,mahayanaFailures:p.v38MahayanaFailures,originActions:p.v38OriginActions,worldCrisisWins:p.v38WorldCrisisWins,worldEdictUses:p.v38WorldEdictUses,natalOriginMarks:p.v38NatalOriginMarks,mahayanaEssence:v33MaterialCount('mat-v38-mahayana-essence'),tribulationPrep:{...p.v38TribulationPrep},world:v38WorldSnapshot()}}
function v38SetPlayerForTest({realmIndex=null,location=null,originInsight=null,authority=null,lawProficiency=null,unity=null,mahayanaEssence=null,natalArtifactId=undefined,natalMarks=null,insight=null,progressFull=false,injury=null}={}){ensureV38MahayanaShape();const p=state.player;if(realmIndex!=null)p.realmIndex=clamp(Number(realmIndex)||0,0,REALMS.length-1);if(location)p.location=location;if(originInsight!=null)p.v38OriginInsight=Math.max(0,Number(originInsight)||0);if(authority!=null)p.v38WorldAuthority=Math.max(0,Number(authority)||0);if(lawProficiency!=null)p.v37LawProficiency=Math.max(0,Number(lawProficiency)||0);if(unity!=null)p.v37Unity=Math.max(0,Number(unity)||0);if(mahayanaEssence!=null){p.mahayanaEssence=Math.max(0,Number(mahayanaEssence)||0);p.materialInventoryById['mat-v38-mahayana-essence']=p.mahayanaEssence}if(natalArtifactId!==undefined)p.natalArtifactId=natalArtifactId;if(natalMarks!=null){p.v38NatalOriginMarks=Math.max(0,Number(natalMarks)||0);if(p.natalArtifactId&&p.equipmentInventory?.[p.natalArtifactId])p.equipmentInventory[p.natalArtifactId].originMarks=p.v38NatalOriginMarks}if(insight!=null)p.insight=Math.max(0,Number(insight)||0);if(injury!=null)p.injury=clamp(Number(injury)||0,0,3);if(progressFull)p.progress=realm().need;p.hp=maxHp();p.qi=maxQi();syncV33AlchemyState();return true}
function renderV38MahayanaPanel(){let panel=$('v38MahayanaPanel');if(!panel){const page=$('page-character');if(!page)return;panel=document.createElement('section');panel.className='panel';panel.id='v38MahayanaPanel';panel.innerHTML='<h2>大乘 · 天地本源</h2><p class="section-tip">大乘不再以普通灵石和经验条为中心。你必须感应天地本源、建立世界权柄、让本命法宝承载界源烙印，并提前准备未来的仙劫。</p><div id="v38MahayanaInfo"></div><div id="v38MahayanaActions"></div>';page.appendChild(panel)}ensureV38MahayanaShape();const p=state.player,info=$('v38MahayanaInfo'),actions=$('v38MahayanaActions');if(!info||!actions)return;const prep=v38TribulationPrepSnapshot();info.innerHTML='<div class="kv"><span>天地本源</span><b>'+p.v38OriginInsight+' / 360</b></div><div class="kv"><span>世界权柄</span><b>'+p.v38WorldAuthority+' / 240</b></div><div class="kv"><span>人界秩序</span><b>'+state.world.v38WorldOrder+' / 100</b></div><div class="kv"><span>本命界源烙印</span><b>'+p.v38NatalOriginMarks+' / 9</b></div><div class="kv"><span>大乘本源髓</span><b>'+v33MaterialCount('mat-v38-mahayana-essence')+'</b></div><div class="kv"><span>渡劫准备总量</span><b>'+prep.total+' / 500</b></div>';let html='';if(v38OriginRegion())html+='<button data-v38-origin>参悟天地本源</button>';if(p.location==='人界议庭'&&p.realmIndex>=34)html+='<button data-v38-authority>处理世界事务</button>';if(['界源海','天穹祖脉'].includes(p.location)&&p.realmIndex>=33)html+='<button data-v38-essence>凝炼大乘本源髓</button>';if(['天穹祖脉','九霄劫台'].includes(p.location)&&p.natalArtifactId)html+='<button data-v38-natal>本命法宝界源化</button>';if(v38TribulationPrepUnlocked()&&p.location==='九霄劫台')for(const k of V38_TRIB_PREP_KEYS)html+='<button data-v38-prep="'+k+'">准备'+({body:'肉身',soul:'元神',law:'法则',artifact:'本命法宝',formation:'阵法'}[k])+'</button>';actions.innerHTML=html||'<div class="section-tip">前往归一圣墟寻找通往【界源海】的道路。</div>';const o=actions.querySelector('[data-v38-origin]');if(o)o.onclick=()=>{const r=v38ContemplateOrigin();showResult(r.ok?'本源有所悟':'无法悟源',r.ok?'天地本源 +'+r.gain+(r.backlash?'，并遭到本源反噬。':''):'原因：'+r.reason,r.ok&&!r.backlash?'good':'bad')};const a=actions.querySelector('[data-v38-authority]');if(a)a.onclick=()=>{const r=v38ExerciseWorldAuthority();showResult(r.ok?'权柄增长':'无法执掌',r.ok?'世界权柄 +'+r.gain:'原因：'+r.reason,r.ok?'good':'bad')};const e=actions.querySelector('[data-v38-essence]');if(e)e.onclick=()=>{const r=v38CraftMahayanaEssence();showResult(r.ok?'本源髓凝成':'无法凝炼',r.ok?'大乘本源髓 +1':'原因：'+r.reason,r.ok?'good':'bad')};const n=actions.querySelector('[data-v38-natal]');if(n)n.onclick=()=>{const r=v38TemperNatalOrigin();showResult(r.ok?'本命融源成功':'无法融源',r.ok?'界源烙印 '+r.marks+'/9':'原因：'+r.reason,r.ok?'good':'bad')};for(const b of actions.querySelectorAll('[data-v38-prep]'))b.onclick=()=>{const r=v38PrepareTribulation(b.dataset.v38Prep);showResult(r.ok?'渡劫准备推进':'准备失败',r.ok?b.textContent+' +'+r.gain:'原因：'+r.reason,r.ok?'good':'bad')}}
function renderV38WorldPanel(){let panel=$('v38WorldPanel');if(!panel){const page=$('page-events');if(!page)return;panel=document.createElement('section');panel.className='panel';panel.id='v38WorldPanel';panel.innerHTML='<h2>人界大势</h2><p class="section-tip">大乘修士已经能改变区域与宗门的实际处境。世界危机的胜负会改变人界秩序、势力关系、宗门贡献与高阶商路。</p><div id="v38WorldInfo"></div><div id="v38WorldActions"></div>';page.appendChild(panel)}ensureV38MahayanaShape();const w=state.world,info=$('v38WorldInfo'),actions=$('v38WorldActions');if(!info||!actions)return;const row=V38_CRISIS_BY_ID[w.v38ActiveCrisisId];info.innerHTML='<div class="kv"><span>人界秩序</span><b>'+w.v38WorldOrder+'/100</b></div><div class="kv"><span>世界危机</span><b>'+(row?esc(row.name):'暂无')+'</b></div><div class="kv"><span>已平定危机</span><b>'+state.player.v38WorldCrisisWins+'</b></div>';let html='';if(state.player.realmIndex>=34&&w.v38CrisisStatus!=='active')html+='<button data-v38-crisis-start>接议庭世界级委托</button>';if(row)html+='<div class="skill-card"><b>'+esc(row.name)+'</b><div class="skill-desc">'+esc(row.desc)+' · 地点：'+esc(row.region)+'</div><button data-v38-crisis-join>介入危机</button></div>';actions.innerHTML=html||'<div class="section-tip">大乘初期后，人界议庭才会把世界级危机交到你手中。</div>';const s=actions.querySelector('[data-v38-crisis-start]');if(s)s.onclick=()=>{const r=v38StartWorldCrisis();showResult(r.ok?'世界危机爆发':'当前无法接令',r.ok?'前往 '+r.region+' 处理危机。':'原因：'+r.reason,r.ok?'major':'bad')};const j=actions.querySelector('[data-v38-crisis-join]');if(j)j.onclick=()=>{const r=v38JoinWorldCrisis(row.id);if(!r.ok)showResult('无法介入','原因：'+r.reason,'bad')}}
const V38_WORLD_ACTORS=Object.freeze([{"id":"actor-v38-council-lord","name":"玄衡道尊","realmIndex":37,"powerId":"power-mortal-council","home":"人界议庭","role":"议庭首座","dao":"spirit","desc":"已在人界议庭坐镇千余年，处理的每一道敕令都会牵动数个大域与宗门。"},{"id":"actor-v38-tianyuan-warden","name":"断空剑主","realmIndex":36,"powerId":"power-tianyuan-alliance","home":"天衡战城","role":"天渊镇守","dao":"sword","desc":"镇守天渊边荒的世界级剑修，领域与剑阵覆盖数百里战线。"},{"id":"actor-v38-origin-hermit","name":"归海老人","realmIndex":37,"powerId":"power-origin-watchers","home":"界源海","role":"界源守望者","dao":"body","desc":"拒绝诸宗供奉，只在有人过度抽取界源时现身，是人界本源平衡的活见证。"},{"id":"actor-v38-heaven-keeper","name":"九霄散人","realmIndex":37,"powerId":"power-heavenline-keepers","home":"九霄劫台","role":"守劫人","dao":"flame","desc":"常年守在劫台之巅，见过许多大乘圆满修士在真正仙劫前止步。"},{"id":"actor-v38-vein-matriarch","name":"天脉圣母","realmIndex":36,"powerId":"power-origin-watchers","home":"天穹祖脉","role":"祖脉护持者","dao":"body","desc":"可直接感知人界祖脉的伤势，对任何破坏世界根基的势力都极为敌视。"},{"id":"actor-v38-wandering-sovereign","name":"无涯真君","realmIndex":35,"powerId":"power-mortal-council","home":"界源海","role":"大乘游修","dao":"sword","desc":"不入常驻宗门，却会参与世界危机；其态度会随人界秩序与玩家的世界贡献发生变化。"}]);
function v38WorldActorRegistry(){return Object.fromEntries(V38_WORLD_ACTORS.map(x=>[x.id,JSON.parse(JSON.stringify(x))]))}

const V39_FORMATIONS=Object.freeze([{"id":"formation-v39-five-elements","name":"五行承雷大阵","focus":"thunder","guard":0.22,"integrity":100,"desc":"均衡分担六重雷劫，适合准备度平均的修士。","cost":{"mat-v39-tribulation-gold":2,"mat-v39-thunder-crystal":2,"mat-v38-tribulation-array-core":1}},{"id":"formation-v39-soul-mirror","name":"太虚照心阵","focus":"heart","guard":0.34,"integrity":100,"desc":"对心魔劫最强，但正面承雷能力较弱。","cost":{"mat-v39-heart-mirror":2,"mat-v39-soul-amber":2,"mat-v38-tribulation-array-core":1}},{"id":"formation-v39-nirvana","name":"涅槃转生阵","focus":"transform","guard":0.3,"integrity":100,"desc":"把雷劫残余导向仙凡蜕变，适合重视最后蜕凡稳定度的构筑。","cost":{"mat-v39-nirvana-dew":1,"mat-v39-life-thread":2,"mat-v38-tribulation-array-core":1}},{"id":"formation-v39-nine-heavens","name":"九霄锁劫仙阵","focus":"all","guard":0.18,"integrity":120,"desc":"成本最高但覆盖雷劫、心魔与蜕变三段，是最稳定的综合阵法。","cost":{"mat-v39-tribulation-gold":2,"mat-v39-thunder-crystal":2,"mat-v39-heart-mirror":1,"mat-v38-tribulation-array-core":2}}]);
