const V39_PILL_RECIPES=Object.freeze(['recipe-v39-thunder-ninefold','recipe-v39-heart-clear','recipe-v39-immortal-transform','recipe-v39-life-return','recipe-v39-law-anchor','recipe-v39-heaven-gate']);
function ensureV39FinaleShape(){
 if(!state?.player||!state?.world)return false;const p=state.player,w=state.world;
 if(p.v39FinaleVersion==null)p.v39FinaleVersion=1;if(p.v39TribulationStatus==null)p.v39TribulationStatus='idle';if(p.v39TribulationAttempt==null)p.v39TribulationAttempt=0;if(p.v39ThunderStage==null)p.v39ThunderStage=0;if(p.v39TribulationFailures==null)p.v39TribulationFailures=0;if(p.v39HeartDemonFailures==null)p.v39HeartDemonFailures=0;if(p.v39TransformationStep==null)p.v39TransformationStep=0;if(p.v39FormationId===undefined)p.v39FormationId=null;if(p.v39FormationIntegrity==null)p.v39FormationIntegrity=0;if(!p.v39PillGuards||typeof p.v39PillGuards!=='object'||Array.isArray(p.v39PillGuards))p.v39PillGuards={thunder:0,heart:0,transform:0,life:0,law:0,ascension:0};for(const k of ['thunder','heart','transform','life','law','ascension'])if(p.v39PillGuards[k]==null)p.v39PillGuards[k]=0;if(p.v39LastFailureStage===undefined)p.v39LastFailureStage=null;if(!Array.isArray(p.v39TribulationHistory))p.v39TribulationHistory=[];if(p.v39AscensionComplete==null)p.v39AscensionComplete=false;if(p.v39TrueImmortalArchive===undefined)p.v39TrueImmortalArchive=null;if(p.tribulationEssence==null)p.tribulationEssence=v33MaterialCount('mat-v39-tribulation-essence');
 if(w.v39AscensionCount==null)w.v39AscensionCount=0;if(w.v39LastAscender===undefined)w.v39LastAscender=null;if(w.v39HeavenGateOpen==null)w.v39HeavenGateOpen=false;if(!state.legacy.trueImmortalArchives||!Array.isArray(state.legacy.trueImmortalArchives))state.legacy.trueImmortalArchives=[];return true
}
function syncV39FinaleState(){if(!ensureV39FinaleShape())return false;const p=state.player;p.tribulationEssence=v33MaterialCount('mat-v39-tribulation-essence');if(p.v39FormationId&&!V39_FORMATION_BY_ID[p.v39FormationId]){p.v39FormationId=null;p.v39FormationIntegrity=0}return true}
function v39FormationRegistry(){return Object.fromEntries(V39_FORMATIONS.map(x=>[x.id,JSON.parse(JSON.stringify(x))]))}
function v39Formation(){ensureV39FinaleShape();return V39_FORMATION_BY_ID[state.player.v39FormationId]||null}
function v39BuildTribulationFormation(id,force=false){ensureV39FinaleShape();const p=state.player,row=V39_FORMATION_BY_ID[id];if(!row)return {ok:false,reason:'missing'};if(p.realmIndex<37&&!force)return {ok:false,reason:'realm'};if(p.location!=='九霄劫台'&&!force)return {ok:false,reason:'location'};if(!force){if(!Object.entries(row.cost||{}).every(([mid,n])=>v33MaterialCount(mid)>=n))return {ok:false,reason:'cost'};for(const [mid,n] of Object.entries(row.cost||{}))v33AddMaterial(mid,-n);advanceDays(24);if(state.flags.dead)return {ok:false,reason:'dead'}}p.v39FormationId=id;p.v39FormationIntegrity=row.integrity||100;addPersonal('【抗劫阵法】你在九霄劫台布成【'+row.name+'】，阵法完整度 '+p.v39FormationIntegrity+'。','major');save();render();return {ok:true,id,integrity:p.v39FormationIntegrity}}
function v39TribulationArtifactScore(kind='thunder'){
 ensureV39FinaleShape();let score=0;for(const {row,rec} of v32EquippedRows()){if(rec?.damaged)continue;const x=row.passive||{};score+=Number(x.tribulationGuard)||0;score+=Number(x[kind+'Guard'])||0;if(rec?.natal)score+=(state.player.v38NatalOriginMarks||0)*.012}return Math.min(.85,score)
}
function v39FormationGuard(kind='thunder'){const f=v39Formation();if(!f||state.player.v39FormationIntegrity<=0)return 0;let x=Number(f.guard)||0;if(f.focus===kind)x+=.16;else if(f.focus==='all')x+=.10;return x*Math.min(1,state.player.v39FormationIntegrity/(f.integrity||100))}
function v39PathGuard(kind){const path=state.player.daoPath;if(path==='body'&&(kind==='body'||kind==='thunder'))return .10;if(path==='spirit'&&(kind==='soul'||kind==='heart'))return .10;if(path==='sword'&&(kind==='law'||kind==='thunder'))return .07;if(path==='flame'&&(kind==='transform'||kind==='thunder'))return .08;return .02}
function v39SkillGuard(kind='thunder'){const learned=state.player.spells||{};let guard=0;for(const row of V31_SPELL_CATALOG){if(!String(row.id||'').startsWith('spell-v39-')||!(row.name in learned))continue;const e=row.effect||{};if(kind==='thunder'||['body','soul','law','artifact','formation','all'].includes(kind))guard+=Number(e.tribulationGuard)||0;guard+=Number(e[kind+'Guard'])||0}return Math.min(.55,guard)}
function v39ArmTribulationPill(recipeId,force=false){ensureV39FinaleShape();const row=V33_RECIPE_BY_ID[recipeId];if(!row||!V39_PILL_RECIPES.includes(recipeId)||!row.effect?.v39Guard)return {ok:false,reason:'recipe'};if(!force){const grade=v33HighestPillGrade(recipeId);if(!grade)return {ok:false,reason:'none'};const used=useV33Pill(recipeId,grade,false);if(!used||typeof used==='string')return {ok:false,reason:used||'use'}}const key=row.effect.v39Guard,value=Math.max(1,Number(row.effect.v39Value)||1);if(key==='life')state.player.v39PillGuards.life=Math.max(1,state.player.v39PillGuards.life||0);else state.player.v39PillGuards[key]=Math.min(60,(state.player.v39PillGuards[key]||0)+value);addPersonal('【渡劫丹药】你备下《'+row.name+'》，'+key+' 护持提升。','good');save();render();return {ok:true,key,value:state.player.v39PillGuards[key]}}
function v39PrepAverage(){const prep=state.player.v38TribulationPrep||{};return ['body','soul','law','artifact','formation'].reduce((a,k)=>a+(Number(prep[k])||0),0)/5}
function v39TribulationReadiness(){ensureV39FinaleShape();const p=state.player,prep=p.v38TribulationPrep||{},formation=v39Formation(),artifactScore=v39TribulationArtifactScore('thunder');const req={realm:p.realmIndex===37,progress:p.progress>=realm().need,location:p.location==='九霄劫台',injury:(p.injury||0)===0,origin:(p.v38OriginInsight||0)>=300,authority:(p.v38WorldAuthority||0)>=170,natal:(p.v38NatalOriginMarks||0)>=7,body:(prep.body||0)>=60,soul:(prep.soul||0)>=60,law:(prep.law||0)>=60,artifact:(prep.artifact||0)>=60,formationPrep:(prep.formation||0)>=60,formation:!!formation&&p.v39FormationIntegrity>=70,antiTribulationArtifact:artifactScore>=.10};return {ready:Object.values(req).every(Boolean),requirements:req,origin:p.v38OriginInsight||0,authority:p.v38WorldAuthority||0,natalMarks:p.v38NatalOriginMarks||0,prep:{...prep},formationId:p.v39FormationId,formationIntegrity:p.v39FormationIntegrity,artifactScore}}
function v39BeginTribulation(force=false){ensureV39FinaleShape();const p=state.player,r=v39TribulationReadiness();if(!force&&!r.ready)return {ok:false,reason:'readiness',readiness:r};if(!['idle','failed'].includes(p.v39TribulationStatus)&&!force)return {ok:false,reason:'active'};if(!force){advanceDays(7);if(state.flags.dead)return {ok:false,reason:'dead'}}p.v39TribulationAttempt++;p.v39TribulationStatus='thunder';p.v39ThunderStage=0;p.v39TransformationStep=0;p.v39LastFailureStage=null;p.location='仙劫雷海';state.world.v39HeavenGateOpen=false;addWorld('【仙劫降临】'+p.name+'于九霄劫台正式引动仙劫，天穹化作六重雷海。','major');addPersonal('【渡劫开始】六重雷劫已经锁定你的气机。现在没有普通退路，只有渡过、败退或身死。','major');save();render();return {ok:true,status:p.v39TribulationStatus,stage:p.v39ThunderStage}}
function v39ThunderStage(){ensureV39FinaleShape();return V39_TRIBULATION_STAGES[state.player.v39ThunderStage]||null}
function v39ThunderScore(row,strategy='balanced'){
 const p=state.player,prep=p.v38TribulationPrep||{},avg=v39PrepAverage(),focus=row.focus==='all'?avg:Number(prep[row.focus])||0;let score=focus*.48+avg*.24+(p.v38OriginInsight||0)*.055+(p.v38WorldAuthority||0)*.045+(p.v38NatalOriginMarks||0)*1.2;score+=(v39TribulationArtifactScore(row.focus==='all'?'thunder':row.focus)+v39FormationGuard(row.focus==='all'?'thunder':row.focus)+v39PathGuard(row.focus)+v39SkillGuard(row.focus==='all'?'thunder':row.focus))*100;score+=(p.v39PillGuards.thunder||0)+(row.focus==='law'?(p.v39PillGuards.law||0):0);if(strategy==='body'&&['body','all'].includes(row.focus))score+=10;if(strategy==='law'&&['law','all'].includes(row.focus))score+=10;if(strategy==='artifact'&&['artifact','formation','all'].includes(row.focus))score+=10;score+=((state.world.v38WorldOrder||50)-50)*.04;return score
}
function v39DamageFormation(n){const p=state.player;if(!p.v39FormationId)return 0;const before=p.v39FormationIntegrity;p.v39FormationIntegrity=Math.max(0,before-Math.max(0,Math.round(n||0)));return before-p.v39FormationIntegrity}
function v39ReducePrep(amount){const prep=state.player.v38TribulationPrep||{};for(const k of ['body','soul','law','artifact','formation'])prep[k]=Math.max(0,(prep[k]||0)-amount)}
function v39RecordHistory(type,data={}){const p=state.player;p.v39TribulationHistory.push({day:dayNumber(),type,...data});p.v39TribulationHistory=p.v39TribulationHistory.slice(-30)}
function v39TribulationFailure(stage,fatalMode=null){ensureV39FinaleShape();const p=state.player,row=typeof stage==='object'?stage:V39_TRIBULATION_STAGES[Math.max(0,(p.v39ThunderStage||1)-1)]||{id:String(stage||'unknown'),name:String(stage||'渡劫失败'),lifeLoss:[400,800]};p.v39TribulationFailures++;p.v39LastFailureStage=row.id||row.name;p.injury=3;p.hp=Math.max(1,Math.floor(maxHp()*.04));const lifeLoss=fatalMode==='survive'?Math.floor((row.lifeLoss?.[0]||400)*.8):rint(row.lifeLoss?.[0]||400,row.lifeLoss?.[1]||900),before=p.lifespan;p.lifespan=Math.max(age()+3,p.lifespan-lifeLoss);v39ReducePrep(p.v39ThunderStage>=4?18:12);v39DamageFormation(p.v39ThunderStage>=4?28:18);const natal=p.natalArtifactId&&p.equipmentInventory?.[p.natalArtifactId];if(natal&&p.v39ThunderStage>=3){natal.damaged=true;if((natal.originMarks||0)>0)natal.originMarks--;p.v38NatalOriginMarks=Math.max(0,natal.originMarks||0)}let fatal=fatalMode==='fatal';if(fatalMode==null&&p.v39ThunderStage>=4)fatal=rand()<clamp(.20+(p.v39ThunderStage-3)*.10-v39TribulationArtifactScore('life')*.25-v39FormationGuard('thunder')*.12,.05,.62);if(fatal&&(p.v39PillGuards.life||0)>0){p.v39PillGuards.life=0;fatal=false;addPersonal('【一线续命】致命劫雷撕碎道体前，续命丹留下的一线生机将你从死关拖了回来。','major')}if(fatal){p.v39TribulationStatus='failed';p.hp=0;p.qi=0;state.flags.dead=true;state.flags.deathCause='渡仙劫失败';state.flags.deathAge=age();state.flags.deathRealm='大乘圆满';state.flags.deathDay=dayNumber();v39RecordHistory('fatal',{stage:row.id});addWorld('【渡劫陨落】'+p.name+'在'+row.name+'中身死道消，仙路断于雷海。','bad');save();render();return {ok:true,outcome:'fatal',stage:row.id,lifeLoss:Math.max(0,before-p.lifespan)}}p.v39TribulationStatus='failed';p.location='九霄劫台';v39RecordHistory('failure',{stage:row.id});addPersonal('【渡劫失败】你从'+row.name+'中重伤退回九霄劫台，必须重新养伤、修复阵法并补足准备。','bad');save();render();return {ok:true,outcome:'failure',stage:row.id,lifeLoss:Math.max(0,before-p.lifespan)}}
function v39ResolveThunder(strategy='balanced',force=null){ensureV39FinaleShape();const p=state.player;if(p.v39TribulationStatus!=='thunder')return {ok:false,reason:'status'};const row=v39ThunderStage();if(!row)return {ok:false,reason:'stage'};const score=v39ThunderScore(row,strategy),roll=force==='success'?0:force==='fail'||force==='fatal'?100:rand()*22-7,success=force==='success'?true:(force==='fail'||force==='fatal'?false:score+roll>=row.difficulty);if(!success)return v39TribulationFailure(row,force==='fatal'?'fatal':force==='fail'?'survive':null);const damaged=v39DamageFormation(row.formationDamage);p.v39ThunderStage++;v39RecordHistory('thunder-pass',{stage:row.id,score:Math.round(score),strategy});addPersonal('【'+row.name+'】你以'+({body:'肉身硬承',law:'法则化解',artifact:'法宝阵法承劫',balanced:'五线平衡'}[strategy]||'五线平衡')+'渡过这一重雷劫。阵法完整度 -'+damaged+'。','major');if(p.v39ThunderStage>=V39_TRIBULATION_STAGES.length){p.v39TribulationStatus='heart';addWorld('【六雷皆过】'+p.name+'扛过六重仙雷，但真正针对道心的心魔劫随即降临。','major')}save();render();return {ok:true,outcome:'success',stage:row.id,score,remaining:V39_TRIBULATION_STAGES.length-p.v39ThunderStage,status:p.v39TribulationStatus}}
function v39HeartScore(strategy='self'){const p=state.player,prep=p.v38TribulationPrep||{};let score=(prep.soul||0)*.48+(prep.law||0)*.20+(p.v37LawProficiency||0)*.055+(p.v38WorldAuthority||0)*.04+(p.v39PillGuards.heart||0)+(p.v39PillGuards.law||0)*.5+(v39TribulationArtifactScore('heart')+v39FormationGuard('heart')+v39PathGuard('heart')+v39SkillGuard('heart'))*100;if(strategy==='self')score+=8;if(strategy==='sever')score+=Math.min(10,(p.v37Unity||0)/15);if(strategy==='past'){const bonds=state.legacy?.pastLifeBonds?.length||0,merit=state.legacy?.merit||0;score+=Math.min(8,bonds*.6+merit*.15)}return score}
function v39ResolveHeartDemon(strategy='self',force=null){ensureV39FinaleShape();const p=state.player;if(p.v39TribulationStatus!=='heart')return {ok:false,reason:'status'};if(!['self','sever','past'].includes(strategy))return {ok:false,reason:'strategy'};const score=v39HeartScore(strategy),success=force==='success'?true:force==='fail'?false:score+(rand()*18-6)>=96;if(!success){p.v39HeartDemonFailures++;p.v37LawProficiency=Math.max(0,(p.v37LawProficiency||0)-18);p.v37Unity=Math.max(0,(p.v37Unity||0)-12);p.v38WorldAuthority=Math.max(0,(p.v38WorldAuthority||0)-12);v39ReducePrep(14);p.injury=3;const before=p.lifespan;p.lifespan=Math.max(age()+3,p.lifespan-rint(500,900));p.v39TribulationStatus='failed';p.location='九霄劫台';p.v39LastFailureStage='heart-demon';v39RecordHistory('heart-failure',{strategy});addPersonal('【心魔劫败】你没能守住唯一真我，道心崩裂后从仙劫中败退。','bad');save();render();return {ok:true,outcome:'failure',score,lifeLoss:before-p.lifespan}}p.v39TribulationStatus='transformation';p.v39TransformationStep=0;p.location='仙凡界隙';v39RecordHistory('heart-pass',{strategy,score:Math.round(score)});addWorld('【心魔已破】'+p.name+'守住真我，雷海散去，仙凡界隙在身前显化。','major');save();render();return {ok:true,outcome:'success',score,status:p.v39TribulationStatus}}
function v39TransformationScore(row,strategy='balanced'){const p=state.player,prep=p.v38TribulationPrep||{},focus=prep[row.focus]||0;let score=focus*.52+v39PrepAverage()*.18+(p.v38OriginInsight||0)*.06+(p.v38NatalOriginMarks||0)*1.4+(p.v39PillGuards.transform||0)+(v39TribulationArtifactScore('transform')+v39FormationGuard('transform')+v39PathGuard('transform')+v39SkillGuard('transform'))*100;if(strategy===row.focus)score+=10;if(strategy==='balanced')score+=4;return score}
function v39ResolveTransformation(strategy='balanced',force=null){ensureV39FinaleShape();const p=state.player;if(p.v39TribulationStatus!=='transformation')return {ok:false,reason:'status'};const row=V39_TRANSFORMATION_STAGES[p.v39TransformationStep];if(!row)return {ok:false,reason:'stage'};const score=v39TransformationScore(row,strategy),success=force==='success'?true:force==='fail'?false:score+(rand()*16-5)>=row.difficulty;if(!success){p.v39TribulationFailures++;p.v39LastFailureStage=row.id;p.v39TribulationStatus='failed';p.realmIndex=37;p.location='九霄劫台';p.injury=3;p.v38OriginInsight=Math.max(0,(p.v38OriginInsight||0)-18);p.v38WorldAuthority=Math.max(0,(p.v38WorldAuthority||0)-12);v39ReducePrep(16);v39DamageFormation(24);const before=p.lifespan;p.lifespan=Math.max(age()+3,p.lifespan-rint(650,1000));v39RecordHistory('transformation-failure',{stage:row.id});addPersonal('【仙凡蜕变失败】'+row.name+'失衡，你保住性命却跌回大乘圆满，只能重新准备。','bad');save();render();return {ok:true,outcome:'failure',stage:row.id,score,lifeLoss:before-p.lifespan}}p.v39TransformationStep++;v39RecordHistory('transformation-pass',{stage:row.id,score:Math.round(score)});addPersonal('【仙凡蜕变】'+row.name+'完成（'+p.v39TransformationStep+'/3）。','major');if(p.v39TransformationStep>=V39_TRANSFORMATION_STAGES.length){p.v39TribulationStatus='ascension';p.realmIndex=38;p.progress=0;p.lifespan=Math.max(p.lifespan,120000);p.hp=maxHp();p.qi=maxQi();state.world.v39HeavenGateOpen=true;addWorld('【渡劫功成】'+p.name+'完成肉身、元神与法则三重仙化，踏入渡劫境，飞升天门已经开启。','major')}save();render();return {ok:true,outcome:'success',stage:row.id,score,step:p.v39TransformationStep,status:p.v39TribulationStatus,realmIndex:p.realmIndex}}
function v39CreateTrueImmortalArchive(){ensureV39FinaleShape();const p=state.player,natal=p.natalArtifactId&&V32_ITEM_BY_ID[p.natalArtifactId];const law=v37Law();return {name:p.name,completedDay:dayNumber(),date:dateLabel(),age:age(),cycles:state.legacy?.cycles||0,daoPath:p.daoPath,law:law?.name||null,manual:p.manual,natalArtifact:natal?.name||null,originInsight:p.v38OriginInsight||0,worldAuthority:p.v38WorldAuthority||0,worldOrder:state.world.v38WorldOrder||0,tribulationAttempts:p.v39TribulationAttempt||0,tribulationFailures:p.v39TribulationFailures||0,heartDemonFailures:p.v39HeartDemonFailures||0,worldCrisisWins:p.v38WorldCrisisWins||0,battleWins:p.battleWins||0,ending:'真仙飞升'}}
function v39AscendToTrueImmortal(force=false){ensureV39FinaleShape();const p=state.player;if(p.v39TribulationStatus!=='ascension'||p.realmIndex!==38)return {ok:false,reason:'status'};if(p.v39TransformationStep<3)return {ok:false,reason:'transformation'};p.location='飞升天门';if(!force){advanceDays(3);if(state.flags.dead)return {ok:false,reason:'dead'}}p.realmIndex=39;p.progress=0;p.lifespan=Math.max(p.lifespan,1000000);p.hp=maxHp();p.qi=maxQi();p.v39AscensionComplete=true;p.v39TribulationStatus='complete';state.flags.gameCompleted=true;state.flags.trueImmortalEnding=true;state.world.v39AscensionCount++;state.world.v39LastAscender=p.name;const archive=v39CreateTrueImmortalArchive();p.v39TrueImmortalArchive=archive;state.legacy.trueImmortalArchives.unshift(JSON.parse(JSON.stringify(archive)));state.legacy.trueImmortalArchives=state.legacy.trueImmortalArchives.slice(0,10);v39RecordHistory('true-immortal',{age:archive.age});addWorld('【飞升真仙】'+p.name+'跨过飞升天门，仙凡蜕变彻底完成，人界长生路第一次真正走到终点。','major');addPersonal('【真仙通关】你从凡人一路走到真仙。当前长期主线已经完成，仙界更高境界只保留未来扩展口。','major');save();render();return {ok:true,outcome:'true-immortal',archive:JSON.parse(JSON.stringify(archive)),realmIndex:p.realmIndex}}
function v39TravelGate(route,to=null){ensureV39FinaleShape();if(!route?.tribulationState)return {ok:true};const s=state.player.v39TribulationStatus;if(route.tribulationState==='thunder')return {ok:s==='thunder',reason:s==='thunder'?'ok':'tribulation',to};if(route.tribulationState==='transformation')return {ok:s==='transformation'||s==='heart',reason:(s==='transformation'||s==='heart')?'ok':'transformation',to};if(route.tribulationState==='ascension')return {ok:s==='ascension'||s==='complete',reason:(s==='ascension'||s==='complete')?'ok':'ascension',to};return {ok:false,reason:'state',to}}
function v39EnemyMechanic(e){return e?.mechanic&&String(e.id||'').startsWith('enemy-v39-')?e.mechanic:null}
function v39EnemyAfterPlayerAction(a,beforeHp){if(!combat)return;const m=v39EnemyMechanic(combat.enemy);if(!m)return;const raw=Math.max(0,beforeHp-combat.enemyHp);if(raw<=0)return;if(m.type==='v39-rift-phase'&&combat.round%2===0){const blocked=Math.min(raw-1,Math.floor(raw*.35));if(blocked>0){combat.enemyHp+=blocked;combat.logs.push('【仙凡错位】界隙虚化抵消 '+blocked+' 点伤害。')}}if(m.type==='v39-gate-law'&&state.player.realmIndex<39){const blocked=Math.min(raw-1,Math.floor(raw*.28));if(blocked>0){combat.enemyHp+=blocked;combat.logs.push('【天门禁律】未成真仙前的力量被天门规则削弱。')}}if(m.type==='v39-heart-copy'&&combat.round%3===0){const reflected=Math.max(1,Math.floor(raw*.18));combat.playerHp=Math.max(1,combat.playerHp-reflected);combat.logs.push('【照心】心魔复制你这一击的部分威势，反震 '+reflected+' 点气血。')}if(m.type==='v39-law-thunder'&&!v37DomainActive()&&!v38WorldEdictActive()){const blocked=Math.min(raw-1,Math.floor(raw*.40));if(blocked>0){combat.enemyHp+=blocked;combat.logs.push('【破法雷鳞】未以领域或世界敕令压住雷鳞，'+blocked+' 点伤害被法雷卸去。')}}}
function v39EnemyAttackEffect(e,dmg){if(!combat)return dmg;const m=v39EnemyMechanic(e);if(!m)return dmg;if(m.type==='v39-thunder-mark'&&combat.round%2===0){dmg=Math.ceil(dmg*1.20);combat.logs.push('【劫雷烙印】连续雷压让这一击额外加重。')}if(m.type==='v39-body-thunder'&&state.player.v38TribulationPrep.body<70){dmg=Math.ceil(dmg*1.28);combat.logs.push('【震体天罡】肉身准备不足，天罡冲击放大。')}if(m.type==='v39-soul-thunder'){const q=Math.floor(combat.playerQi*.06);combat.playerQi=Math.max(0,combat.playerQi-q);if(q>0)combat.logs.push('【识海轰鸣】九霄魂雷抽走 '+q+' 点灵力。')}if(m.type==='v39-transform-drain'){const keys=['body','soul','law'],key=keys[(combat.round-1)%keys.length],prep=state.player.v38TribulationPrep||{},before=prep[key]||0;prep[key]=Math.max(0,before-2);combat.v39TransformSuppressed=2;if(prep[key]!==before)combat.logs.push('【逆蜕】仙凡错力侵蚀 '+key+' 准备 '+(before-prep[key])+' 点。')}if(m.type==='v39-last-heart'&&combat.round%2===0){const guard=v39SkillGuard('heart')+v39TribulationArtifactScore('heart')+v39FormationGuard('heart');const mult=guard>=.25?1.08:1.35;dmg=Math.ceil(dmg*mult);combat.logs.push(guard>=.25?'【前尘聚影】明心护持压住了大半旧念反噬。':'【前尘聚影】旧缘与失败记忆反扑，心障攻势暴涨。')}if(m.type==='v39-immortal-pressure'&&state.player.realmIndex<39){dmg=Math.ceil(dmg*1.45);combat.logs.push('【仙威】真仙境以下承受额外压制。')}return dmg}
function v39AfterCombatRound(){if(!combat)return;if((combat.v39TransformSuppressed||0)>0)combat.v39TransformSuppressed--}
function onV39CombatWin(e){ensureV39FinaleShape();if(!e||e.nonLethal||!String(e.id||'').startsWith('enemy-v39-'))return null;let gained=0;if(state.player.battleWins%3===0){v33AddMaterial('mat-v39-tribulation-essence',1);gained=1}return {tribulationEssence:gained}}
function v39CatalogSnapshot(){return {realms:REALMS.length,regions:Object.keys(LOCATIONS).length,routes:TRAVEL_ROUTES.length,materials:V33_MATERIAL_CATALOG.length,recipes:V33_RECIPE_CATALOG.length,manuals:V31_MANUAL_CATALOG.length,spells:V31_SPELL_CATALOG.length,equipment:V32_EQUIPMENT_CATALOG.length,artifacts:V32_EQUIPMENT_CATALOG.filter(x=>x.trueArtifact).length,enemies:ENEMIES.length,auctionPool:V35_AUCTION_POOL.length,formations:V39_FORMATIONS.length,thunderStages:V39_TRIBULATION_STAGES.length,transformationStages:V39_TRANSFORMATION_STAGES.length}}
function v39StateSnapshot(){ensureV39FinaleShape();const p=state.player;return {status:p.v39TribulationStatus,attempt:p.v39TribulationAttempt,thunderStage:p.v39ThunderStage,failures:p.v39TribulationFailures,heartFailures:p.v39HeartDemonFailures,transformationStep:p.v39TransformationStep,formationId:p.v39FormationId,formationIntegrity:p.v39FormationIntegrity,pillGuards:{...p.v39PillGuards},lastFailure:p.v39LastFailureStage,ascensionComplete:p.v39AscensionComplete,archive:p.v39TrueImmortalArchive?JSON.parse(JSON.stringify(p.v39TrueImmortalArchive)):null,readiness:v39TribulationReadiness()}}
function v39SetPlayerForTest({realmIndex=null,location=null,progressFull=false,injury=null,originInsight=null,authority=null,natalMarks=null,lawProficiency=null,unity=null,prep=null,status=null,formationId=undefined,formationIntegrity=null,battleWins=null}={}){ensureV39FinaleShape();const p=state.player;if(realmIndex!=null)p.realmIndex=clamp(Number(realmIndex)||0,0,REALMS.length-1);if(location)p.location=location;if(progressFull)p.progress=realm().need;if(injury!=null)p.injury=clamp(Number(injury)||0,0,3);if(originInsight!=null)p.v38OriginInsight=Math.max(0,Number(originInsight)||0);if(authority!=null)p.v38WorldAuthority=Math.max(0,Number(authority)||0);if(natalMarks!=null){p.v38NatalOriginMarks=Math.max(0,Number(natalMarks)||0);if(p.natalArtifactId&&p.equipmentInventory?.[p.natalArtifactId])p.equipmentInventory[p.natalArtifactId].originMarks=p.v38NatalOriginMarks}if(lawProficiency!=null)p.v37LawProficiency=Math.max(0,Number(lawProficiency)||0);if(unity!=null)p.v37Unity=Math.max(0,Number(unity)||0);if(prep)for(const [k,v] of Object.entries(prep))if(['body','soul','law','artifact','formation'].includes(k))p.v38TribulationPrep[k]=clamp(Number(v)||0,0,100);if(status!=null)p.v39TribulationStatus=status;if(formationId!==undefined)p.v39FormationId=formationId;if(formationIntegrity!=null)p.v39FormationIntegrity=Math.max(0,Number(formationIntegrity)||0);if(battleWins!=null)p.battleWins=Math.max(0,Number(battleWins)||0);p.hp=maxHp();p.qi=maxQi();return true}
function v39FinaleText(){ensureV39FinaleShape();const p=state.player;if(p.v39TribulationStatus==='complete')return '真仙通关';if(p.v39TribulationStatus==='thunder')return '雷劫 '+(p.v39ThunderStage+1)+'/6';if(p.v39TribulationStatus==='heart')return '心魔劫';if(p.v39TribulationStatus==='transformation')return '仙凡蜕变 '+(p.v39TransformationStep+1)+'/3';if(p.v39TribulationStatus==='ascension')return '待飞升';if(p.v39TribulationStatus==='failed')return '渡劫失败待重整';return '未引劫'}
function renderV39FinalePanel(){let panel=$('v39FinalePanel');if(!panel){const page=$('page-events');if(!page)return;panel=document.createElement('section');panel.className='panel';panel.id='v39FinalePanel';panel.innerHTML='<h2>渡劫 · 飞升 · 真仙终局</h2><p class="section-tip">V3.9 将 V3.8 五维准备转化为真正仙劫：六重雷劫、心魔劫、三重仙凡蜕变与最终飞升。失败代价随阶段上升，后段雷劫可能真正身死。</p><div id="v39FinaleInfo"></div><div id="v39FinaleActions"></div>';page.appendChild(panel)}ensureV39FinaleShape();const p=state.player,info=$('v39FinaleInfo'),actions=$('v39FinaleActions');if(!info||!actions)return;if(p.realmIndex<37&&p.v39TribulationStatus==='idle'){info.innerHTML='<div class="section-tip">至少大乘圆满后，九霄劫台才会真正回应你的渡劫准备。</div>';actions.innerHTML='';return}const r=v39TribulationReadiness(),f=v39Formation();info.innerHTML='<div class="kv"><span>终局状态</span><b>'+v39FinaleText()+'</b></div><div class="kv"><span>渡劫尝试</span><b>'+p.v39TribulationAttempt+' 次 · 失败 '+p.v39TribulationFailures+' 次</b></div><div class="kv"><span>阵法</span><b>'+(f?f.name+' · 完整 '+p.v39FormationIntegrity:'未布置')+'</b></div><div class="kv"><span>抗劫法宝评分</span><b>'+Math.round(r.artifactScore*100)+'</b></div><div class="kv"><span>五维准备</span><b>'+['body','soul','law','artifact','formation'].map(k=>k+':'+(p.v38TribulationPrep[k]||0)).join(' · ')+'</b></div>';let html='';if(['idle','failed'].includes(p.v39TribulationStatus)){html+='<div class="skill-card"><b>抗劫阵法</b><div class="event-actions">'+V39_FORMATIONS.map(x=>'<button data-v39-formation="'+x.id+'">'+x.name+'</button>').join('')+'</div></div>';html+='<div class="skill-card"><b>渡劫丹药</b><div class="event-actions">'+V39_PILL_RECIPES.map(id=>'<button data-v39-pill="'+id+'">'+(V33_RECIPE_BY_ID[id]?.name||id)+'</button>').join('')+'</div></div><div class="event-actions"><button data-v39-start '+(!r.ready?'disabled':'')+'>正式引动仙劫</button></div>'}else if(p.v39TribulationStatus==='thunder'){const row=v39ThunderStage();html='<div class="skill-card"><b>'+row.name+'</b><div class="skill-desc">本重侧重：'+row.focus+' · 难度 '+row.difficulty+'</div><div class="event-actions"><button data-v39-thunder="body">肉身硬承</button><button data-v39-thunder="law">法则化解</button><button data-v39-thunder="artifact">法宝阵法承劫</button><button data-v39-thunder="balanced">五线平衡</button></div></div>'}else if(p.v39TribulationStatus==='heart'){html='<div class="skill-card"><b>心魔劫</b><div class="skill-desc">心魔会借你最深的执念与前尘塑形。前尘只能提供有限帮助，不能替你跨过道心本身。</div><div class="event-actions"><button data-v39-heart="self">守住唯一真我</button><button data-v39-heart="sever">斩断执念</button><button data-v39-heart="past">借前尘照见今生</button></div></div>'}else if(p.v39TribulationStatus==='transformation'){const row=V39_TRANSFORMATION_STAGES[p.v39TransformationStep];html='<div class="skill-card"><b>'+row.name+'</b><div class="skill-desc">仙凡蜕变必须依次重铸肉身、元神与法则。</div><div class="event-actions"><button data-v39-transform="'+row.focus+'">专注'+row.name+'</button><button data-v39-transform="balanced">平衡蜕变</button></div></div>'}else if(p.v39TribulationStatus==='ascension'){html='<div class="event-actions"><button data-v39-ascend>跨过飞升天门 · 成就真仙</button></div>'}else if(p.v39TribulationStatus==='complete'){const a=p.v39TrueImmortalArchive;html='<div class="skill-card"><b>真仙通关档案</b><div class="skill-desc">'+(a?('飞升年龄 '+a.age+' · 轮回 '+a.cycles+' · 道途 '+a.daoPath+' · 世界秩序 '+a.worldOrder):'档案已完成')+'</div></div>'}actions.innerHTML=html;actions.querySelectorAll('[data-v39-formation]').forEach(b=>b.onclick=()=>{const x=v39BuildTribulationFormation(b.dataset.v39Formation);showResult(x.ok?'阵法布成':'无法布阵',x.ok?'阵法完整度 '+x.integrity:'原因：'+x.reason,x.ok?'good':'bad')});actions.querySelectorAll('[data-v39-pill]').forEach(b=>b.onclick=()=>{const x=v39ArmTribulationPill(b.dataset.v39Pill);showResult(x.ok?'渡劫丹药已备':'无法使用',x.ok?'护持已计入仙劫准备':'原因：'+x.reason,x.ok?'good':'bad')});const start=actions.querySelector('[data-v39-start]');if(start)start.onclick=()=>{const x=v39BeginTribulation();if(!x.ok)showResult('不能引劫','准备尚未完整。','bad')};actions.querySelectorAll('[data-v39-thunder]').forEach(b=>b.onclick=()=>{const x=v39ResolveThunder(b.dataset.v39Thunder);showResult(x.outcome==='success'?'雷劫已过':'雷劫失败',x.outcome==='success'?'继续面对下一阶段。':(x.outcome==='fatal'?'身死道消。':'重伤退回九霄劫台。'),x.outcome==='success'?'good':'bad')});actions.querySelectorAll('[data-v39-heart]').forEach(b=>b.onclick=()=>{const x=v39ResolveHeartDemon(b.dataset.v39Heart);showResult(x.outcome==='success'?'心魔已破':'道心失守',x.outcome==='success'?'进入仙凡蜕变。':'本轮渡劫失败。',x.outcome==='success'?'good':'bad')});actions.querySelectorAll('[data-v39-transform]').forEach(b=>b.onclick=()=>{const x=v39ResolveTransformation(b.dataset.v39Transform);showResult(x.outcome==='success'?'仙凡蜕变推进':'蜕变失败',x.outcome==='success'?'当前进度 '+x.step+'/3':'跌回大乘圆满。',x.outcome==='success'?'good':'bad')});const ascend=actions.querySelector('[data-v39-ascend]');if(ascend)ascend.onclick=()=>{const x=v39AscendToTrueImmortal();showResult(x.ok?'飞升真仙':'无法飞升',x.ok?'凡人到真仙的当前长期主线正式通关。':'原因：'+x.reason,x.ok?'good':'bad')}}

