function findNpcBattleAlly(enemy){ensureNpcLifeShape();if(!state||state.flags.dead||enemy?.nonLethal)return null;const forced=Number(state.flags.forceNpcAllyId)||0;if(forced){state.flags.forceNpcAllyId=null;const n=state.npcs.find(x=>x.id===forced);if(n&&n.alive&&n.location===state.player.location&&n.injury<3)return n}const candidates=state.npcs.filter(n=>n.alive&&n.known&&n.location===state.player.location&&(n.relation||0)>=50&&(n.grudge||0)<20&&(n.injury||0)<3);if(!candidates.length)return null;candidates.sort((a,b)=>((b.relation||0)+b.realmIndex*3+(b.favorDebt||0)*8)-((a.relation||0)+a.realmIndex*3+(a.favorDebt||0)*8));const best=candidates[0],chance=clamp(.18+(best.relation||0)/180+best.courage/700+(best.favorDebt||0)*.06,.35,.90);return rand()<chance?best:null}
