 if(typeof n!=='object')n=state.npcs.find(x=>x.id===Number(n));if(!n||!n.alive)return null;ensureNpcConsequenceShape();const today=dayNumber(),old=n.faction;if(!forced&&n.lastFactionChangeDay&&today-n.lastFactionChangeDay<180)return null;let next=target;if(!next){if(old==='散修'){const choices=npcFactionJoinChoices(n);if(!choices.length)return null;next=pick(choices)}else next='散修'}if(!['散修','青云宗','玄水帮','血刀门'].includes(next)||next===old)return null;if(!forced&&old!=='散修'&&next!=='散修')return null;
