const SECT_PEER_DEFAULTS=[
 {id:'qin-wuya',name:'秦无涯',age:27,realmIndex:8,progress:58,talent:118,merit:72,daoPath:'sword',ambition:88},
 {id:'luo-qingshuang',name:'洛清霜',age:31,realmIndex:10,progress:34,talent:112,merit:184,daoPath:'spirit',ambition:78},
 {id:'pei-lie',name:'裴烈',age:35,realmIndex:7,progress:76,talent:108,merit:92,daoPath:'body',ambition:93},
 {id:'song-zhiwei',name:'宋知微',age:29,realmIndex:9,progress:49,talent:121,merit:138,daoPath:'flame',ambition:70},
 {id:'cheng-yue',name:'程岳',age:46,realmIndex:11,progress:22,talent:103,merit:226,daoPath:'body',ambition:64},
 {id:'xie-lingzhou',name:'谢灵舟',age:24,realmIndex:6,progress:67,talent:126,merit:84,daoPath:'sword',ambition:95}
];
function createSectMentorStates(){const out={};for(const [id,d] of Object.entries(SECT_MENTOR_LIFE_DEFAULTS))out[id]={id,bornDay:1-d.age*360,realmIndex:d.realmIndex,progress:d.progress,talent:d.talent,alive:true,retreatUntil:0,breakthroughAttempts:0,breakthroughs:0};return out}
function peerRankFor(x){if(x.realmIndex>=19&&x.merit>=700)return '宗门长老';if(x.realmIndex>=14&&x.merit>=360)return '宗门执事';if(x.realmIndex>=10&&x.merit>=180)return '真传弟子';if(x.realmIndex>=3&&x.merit>=60)return '内门弟子';return '外门弟子'}
function createSectPeers(){return SECT_PEER_DEFAULTS.map(d=>({...d,bornDay:1-d.age*360,alive:true,relation:0,rivalry:0,rank:peerRankFor(d),breakthroughs:0}))}
function sectPersonAge(x){return Math.max(0,Math.floor((dayNumber()-(x.bornDay||1))/360))}
function ensureSectLifeShape(){const p=state.player,w=state.world;if(p.sectPrestige==null)p.sectPrestige=0;if(p.sectRivalId===undefined)p.sectRivalId=null;if(p.sectRivalWins==null)p.sectRivalWins=0;if(p.sectRivalLosses==null)p.sectRivalLosses=0;if(p.sectInternalEvents==null)p.sectInternalEvents=0;if(!w.sectMentors||typeof w.sectMentors!=='object')w.sectMentors=createSectMentorStates();for(const [id,d] of Object.entries(createSectMentorStates())){if(!w.sectMentors[id])w.sectMentors[id]=d}if(!Array.isArray(w.sectPeers)||!w.sectPeers.length)w.sectPeers=createSectPeers();if(w.sectEvent===undefined)w.sectEvent=null;if(w.nextSectEventDay==null)w.nextSectEventDay=75;if(w.sectEventCount==null)w.sectEventCount=0}
function sectMentorState(id){ensureSectLifeShape();return state.world.sectMentors[id]||null}
function mentorLifeText(id){const s=sectMentorState(id);if(!s)return '不详';if(!s.alive)return '已故';const ageNow=sectPersonAge(s),ret=s.retreatUntil>dayNumber()?' · 闭关中 '+(s.retreatUntil-dayNumber())+'日':'';return ageNow+'岁 · '+REALMS[Math.min(s.realmIndex,REALMS.length-1)].name+ret}
function sectPeer(id){ensureSectLifeShape();return state.world.sectPeers.find(x=>x.id===id)||null}
function ensureSectRival(){ensureSectLifeShape();const p=state.player;if(!isSectMember()||sectRankIndex()<1)return null;let current=sectPeer(p.sectRivalId);if(current&&current.alive)return current;const alive=state.world.sectPeers.filter(x=>x.alive);if(!alive.length){p.sectRivalId=null;return null}alive.sort((a,b)=>Math.abs(a.realmIndex-p.realmIndex)-Math.abs(b.realmIndex-p.realmIndex)||(b.merit+a.ambition)-(a.merit+b.ambition));current=alive[0];p.sectRivalId=current.id;addPersonal('【同门竞争】宗门上下开始把你与'+current.name+'并列比较，你们逐渐形成长期竞争关系。','major');return current}
function sectRival(){return ensureSectRival()}
function mentorBreakthroughChance(s){return clamp(.72-majorRealmStage(s.realmIndex)*.08+(s.talent-100)/500,.30,.82)}
function finishMentorRetreat(id,forced=null){const s=sectMentorState(id),m=SECT_MENTORS[id];if(!s||!s.alive)return false;s.retreatUntil=0;s.breakthroughAttempts=(s.breakthroughAttempts||0)+1;const success=forced===null?rand()<mentorBreakthroughChance(s):!!forced;if(success&&s.realmIndex<REALMS.length-1){s.realmIndex++;s.progress=12;s.breakthroughs=(s.breakthroughs||0)+1;addWorld('青云宗'+m.title+'【'+m.name+'】出关，修为突破至'+REALMS[s.realmIndex].name+'。','major');if(state.player.sectMentor===id)addPersonal('你的师父'+m.name+'闭关有成，修为更进一步。','good')}else{s.progress=Math.max(48,s.progress*.55);addWorld('青云宗'+m.title+'【'+m.name+'】闭关出关，此次未能再破一境。');if(state.player.sectMentor===id)addPersonal('你的师父'+m.name+'闭关出关，但此番未能突破。')}return success}
function simulateSectMentor(id){const s=sectMentorState(id),m=SECT_MENTORS[id];if(!s||!s.alive)return;const today=dayNumber(),ageNow=sectPersonAge(s),life=realmLifespanFloor(s.realmIndex);if(ageNow>=life){s.alive=false;s.retreatUntil=0;addWorld('青云宗'+m.title+'【'+m.name+'】寿元耗尽，坐化于山门。','major');if(state.player.sectMentor===id)addPersonal('【师承变故】你的师父'+m.name+'寿尽坐化。你可以改投仍在世的长老，但原有师徒情分只能保留一半。','bad');return}if(s.retreatUntil&&today>=s.retreatUntil){finishMentorRetreat(id);return}const rate=(s.talent/100)*npcCultivationRate(s.realmIndex)*(s.retreatUntil>today?2.8:.45);s.progress+=rate;if(s.progress>=78&&!s.retreatUntil&&s.realmIndex<REALMS.length-1&&rand()<.0025){s.retreatUntil=today+rint(45,90);addWorld(m.title+'【'+m.name+'】封闭洞府，开始冲击下一境。');if(state.player.sectMentor===id)addPersonal('【师门动态】'+m.name+'已经闭关，出关前无法再正式请教。','major')}}
function simulateSectPeer(x){if(!x.alive)return;const ageNow=sectPersonAge(x),life=realmLifespanFloor(x.realmIndex);if(ageNow>=life){x.alive=false;addWorld('青云宗弟子【'+x.name+'】寿尽坐化。');if(state.player.sectRivalId===x.id)addPersonal('与你争了许多年的'+x.name+'寿元耗尽，这段同门竞争也就此结束。','major');return}x.progress+=(x.talent/100)*npcCultivationRate(x.realmIndex)*(.75+rand()*.45);if(x.progress>=100&&x.realmIndex<REALMS.length-1){x.progress-=100;x.realmIndex++;x.breakthroughs=(x.breakthroughs||0)+1;if(rand()<.35)addWorld('青云宗弟子【'+x.name+'】突破至'+REALMS[x.realmIndex].name+'。')}if(dayNumber()%10===0)x.merit+=1+Math.floor(x.ambition/35)+rint(0,1);const old=x.rank;x.rank=peerRankFor(x);if(old!==x.rank)addWorld('青云宗【'+x.name+'】凭修为与功绩晋升为'+x.rank+'。','major')}
function createSectInternalEvent(type=null,force=false){ensureSectLifeShape();if(!isSectMember()||sectRankIndex()<1)return null;if(state.world.sectEvent&&!force)return state.world.sectEvent;const rival=sectRival();const ids=['duel','allocation','lecture'];type=type||ids[state.world.sectEventCount%ids.length];if(type==='duel'&&!rival)type='lecture';const today=dayNumber();let e;if(type==='duel')e={id:'duel',title:'青云论剑小比',text:'宗门安排同代弟子公开切磋。你的长期竞争对手 '+rival.name+' 已经报名。',peerId:rival.id,start:today,end:today+25};else if(type==='allocation')e={id:'allocation',title:'秘库配额评议',text:'宗门拿出一批紧缺修炼资源，由内门以上弟子按功绩、声望与师承争取。',start:today,end:today+20};else e={id:'lecture',title:'诸峰讲法会',text:'四峰轮流公开讲法，同门可回山听讲。若讲法者正是你的师父，师徒情分也会有所增长。',mentorId:Object.keys(SECT_MENTORS).find(id=>sectMentorState(id)?.alive)||'sword',start:today,end:today+18};state.world.sectEvent=e;addWorld('【青云宗内务】'+e.title+'开始。');if(state.player.location==='青云山')addPersonal('宗门内部事件【'+e.title+'】已经开始。','major');return e}
function finishSectInternalEvent(){state.player.sectInternalEvents=(state.player.sectInternalEvents||0)+1;state.world.sectEventCount=(state.world.sectEventCount||0)+1;state.world.sectEvent=null;state.world.nextSectEventDay=dayNumber()+rint(60,100)}
function simulateSectLife(){ensureSectLifeShape();for(const id of Object.keys(SECT_MENTORS))simulateSectMentor(id);for(const x of state.world.sectPeers)simulateSectPeer(x);ensureSectRival();const e=state.world.sectEvent,today=dayNumber();if(e&&today>e.end){addWorld('【青云宗内务】'+e.title+'已经结束。');state.world.sectEvent=null;state.world.nextSectEventDay=today+rint(50,80)}if(!state.world.sectEvent&&isSectMember()&&sectRankIndex()>=1&&today>=state.world.nextSectEventDay)createSectInternalEvent()}
function startSectInternalEvent(){ensureSectLifeShape();const e=state.world.sectEvent;if(!e)return showResult('暂无内务','目前没有需要你参与的宗门内部事件。');if(state.player.location!=='青云山')return showResult('不在山门','宗门内部活动需要回到青云山参加。','bad');if(e.id==='duel'){const r=sectPeer(e.peerId);if(!r||!r.alive){finishSectInternalEvent();save();render();return showResult('对手缺席','原定对手已经无法参加，本次小比自动结束。')}const rr=Math.min(r.realmIndex,REALMS.length-1),hp=Math.max(120,Math.floor(REALMS[rr].maxHp*.86)),lo=Math.max(10,Math.floor(12+rr*5.2)),enemy={name:r.name,kind:'宗门同门',realm:rr,hp,atk:[lo,Math.floor(lo*1.35)],reward:{stones:[0,0],herbs:[0,0],rep:0},nonLethal:true,sectInternalDuel:true,peerId:r.id};addPersonal('【青云论剑】你与'+r.name+'登台切磋，胜负会影响你们在宗门中的名声与竞争关系。','major');startCombat(enemy);return}return resolveSectInternalEvent('attend')}
function resolveSectInternalEvent(choice='attend'){const e=state.world.sectEvent;if(!e)return;if(state.player.location!=='青云山')return showResult('不在山门','需要回青云山参加。','bad');if(e.id==='duel')return startSectInternalEvent();if(livingActionGuard())return;if(e.id==='allocation'){if(state.player.sectContribution<25)return showResult('贡献不足','参与秘库配额评议需要先拿出25点贡献作为功绩抵扣。','bad');state.player.sectContribution-=25;const rival=sectRival(),score=(state.player.sectPrestige||0)*4+sectRankIndex()*15+(state.player.sectMentorBond||0)*3+rint(0,24),opposition=35+(rival?Math.floor(rival.merit/20)+Math.floor(rival.ambition/10):0);if(score>=opposition){const rare=1+(sectRankIndex()>=3?1:0);state.player.rareMaterials=(state.player.rareMaterials||0)+rare;state.player.insight=(state.player.insight||0)+(sectRankIndex()>=2?1:0);state.player.sectPrestige=(state.player.sectPrestige||0)+4;addPersonal('【秘库评议】你凭资历与声望争到资源配额，高阶灵材 +'+rare+(sectRankIndex()>=2?'，悟道点 +1':'')+'。','major');showResult('争取成功','你拿到了本轮秘库配额。','good')}else{state.player.sectPrestige=Math.max(0,(state.player.sectPrestige||0)+1);if(rival)rival.merit+=8;addPersonal('【秘库评议】你没争过其他同门，本次只积累了些许宗门资历。','bad');showResult('未获配额','本轮资源被其他同门拿走。','bad')}finishSectInternalEvent();save();render();return}const mid=e.mentorId,m=SECT_MENTORS[mid],s=sectMentorState(mid);advanceDays(1);if(state.flags.dead)return;state.player.manualProf+=25;state.player.sectPrestige=(state.player.sectPrestige||0)+1;let extra='';if(s&&s.alive&&state.player.sectMentor===mid){state.player.sectMentorBond=(state.player.sectMentorBond||0)+1;extra='，师徒情分 +1'}addPersonal('【诸峰讲法】你听完'+m.name+'一日讲法，功法熟练度 +25，宗门资历 +1'+extra+'。','good');finishSectInternalEvent();save();render();showResult('讲法会结束','功法熟练度 +25'+extra,'good')}
function onSectInternalCombatResult(win,e){if(!e||!e.sectInternalDuel)return;const r=sectPeer(e.peerId);if(win){state.player.sectRivalWins=(state.player.sectRivalWins||0)+1;state.player.sectPrestige=(state.player.sectPrestige||0)+5;state.player.sectContribution+=20;if(r){r.relation-=3;r.rivalry=(r.rivalry||0)+8}addPersonal('【同门小比】你击败'+(r?r.name:e.name)+'，宗门资历 +5，贡献 +20。','major')}else{state.player.sectRivalLosses=(state.player.sectRivalLosses||0)+1;state.player.sectPrestige=Math.max(0,(state.player.sectPrestige||0)-2);if(r){r.merit+=15;r.relation-=2;r.rivalry=(r.rivalry||0)+5}addPersonal('【同门小比】你败给'+(r?r.name:e.name)+'，对方在宗门中的声势更盛。','bad')}finishSectInternalEvent()}
function chooseSectMentor(id){ensureSectLifeShape();const p=state.player,m=SECT_MENTORS[id],s=sectMentorState(id);if(!isSectMember()||sectRankIndex()<1)return showResult('尚无拜师资格','晋升内门后才可正式择师。','bad');if(p.location!=='青云山')return showResult('不在山门','拜师需要回到青云山。','bad');if(!m||!s||!s.alive)return showResult('无法拜师','这位长老已经不在人世。','bad');if(s.retreatUntil>dayNumber())return showResult('长老闭关','这位长老正在闭关，暂不收徒。','bad');if(p.sectMentor){const old=sectMentorState(p.sectMentor);if(old&&old.alive)return showResult('已有师承','你已经拜入 '+SECT_MENTORS[p.sectMentor].name+' 门下，师父仍在世时不能随意改投。','bad');p.sectMentorBond=Math.floor((p.sectMentorBond||0)*.5)}p.sectMentor=id;p.sectLastMentorDay=0;addPersonal('你正式拜'+m.title+'【'+m.name+'】为师。','major');save();render();showResult('拜师完成',m.title+' · '+m.name+'\n'+m.desc,'good')}
function seekMentorGuidance(){ensureSectLifeShape();const p=state.player;if(!p.sectMentor)return showResult('尚无师承','先选择一位师父。','bad');if(p.location!=='青云山')return showResult('不在山门','请教师父需要回到青云山。','bad');const m=SECT_MENTORS[p.sectMentor],s=sectMentorState(p.sectMentor);if(!s||!s.alive)return showResult('师承已断','师父已经坐化。你可以改投仍在世的长老，原有师徒情分保留一半。','bad');if(s.retreatUntil>dayNumber())return showResult('师父闭关','师父正在冲击下一境，距离预计出关还有 '+(s.retreatUntil-dayNumber())+' 日。','bad');const cd=mentorLessonCooldown();if(cd>0)return showResult('请教冷却','师父最近已经指点过你，还需 '+cd+' 日。','bad');if(p.sectContribution<8)return showResult('贡献不足','每次正式请教需从自己的宗门配额中扣除 8 点贡献。','bad');if(livingActionGuard())return;p.sectContribution-=8;p.sectMentorBond=(p.sectMentorBond||0)+1;p.sectLastMentorDay=dayNumber();p.manualProf+=30;let pathGain=0,insightGain=0,rareGain=0;if(m.path===p.daoPath&&p.daoPath!=='none'){pathGain=15;p.daoMastery=(p.daoMastery||0)+pathGain}if(p.sectMentorBond===3||p.sectMentorBond===6)insightGain=1;if(p.sectMentorBond===6)rareGain=1;p.insight=(p.insight||0)+insightGain;p.rareMaterials=(p.rareMaterials||0)+rareGain;advanceDays(1);if(state.flags.dead)return;addPersonal('【师承】'+m.name+'指点你一日，师徒情分提升至 '+p.sectMentorBond+'，功法熟练度 +30'+(pathGain?'，同道修行使道途熟练 +'+pathGain:'')+(insightGain?'，悟道点 +'+insightGain:'')+(rareGain?'，获赠高阶灵材 +'+rareGain:'')+'。','good');save();render();showResult('师父指点','师徒情分 '+p.sectMentorBond+'\n功法熟练度 +30'+(pathGain?'\n道途熟练 +'+pathGain:'')+(insightGain?'\n悟道点 +'+insightGain:'')+(rareGain?'\n高阶灵材 +'+rareGain:''),'good')}
function renderSectLifePanel(info,actions){if(!isSectMember())return;ensureSectLifeShape();const p=state.player,r=sectRival(),mentorRows=Object.values(SECT_MENTORS).map(m=>'<div class="kv"><span>'+m.title+' · '+m.name+'</span><b>'+mentorLifeText(m.id)+'</b></div>').join(''),peerRows=state.world.sectPeers.filter(x=>x.alive).sort((a,b)=>b.merit-a.merit).map(x=>'<div class="kv"><span>'+x.name+(r&&r.id===x.id?' · 当前对手':'')+'</span><b>'+x.rank+' · '+REALMS[Math.min(x.realmIndex,25)].name+' · 功绩'+x.merit+'</b></div>').join('');info.innerHTML+='<div class="skill-card"><div class="skill-head"><b>宗门人物动态</b><span>资历 '+(p.sectPrestige||0)+'</span></div><div class="skill-desc">同门小比 '+(p.sectRivalWins||0)+'胜/'+(p.sectRivalLosses||0)+'负 · 已参与内部事件 '+(p.sectInternalEvents||0)+' 次</div></div>'+mentorRows+'<div class="skill-card"><div class="skill-head"><b>同门竞争</b><span>'+(r?r.name:'暂无固定对手')+'</span></div><div class="skill-desc">'+(peerRows||'暂无仍在世的主要同门。')+'</div></div>';const current=p.sectMentor?sectMentorState(p.sectMentor):null;if(p.sectMentor&&current&&!current.alive){actions.innerHTML+='<div class="section-tip">你的原师父已经坐化，可改投仍在世的长老；原师徒情分折半保留。</div><div class="event-actions">'+Object.values(SECT_MENTORS).filter(x=>sectMentorState(x.id)?.alive).map(x=>'<button data-sect-remaster="'+x.id+'">改投 '+x.name+'</button>').join('')+'</div>'}const e=state.world.sectEvent;if(e){actions.innerHTML+='<div class="skill-card"><div class="skill-head"><b>宗门内务：'+e.title+'</b><span>剩余 '+Math.max(0,e.end-dayNumber()+1)+' 日</span></div><div class="skill-desc">'+e.text+'</div></div><div class="event-actions"><button class="primary" data-sect-internal>'+(e.id==='duel'?'登台切磋':e.id==='allocation'?'争取秘库配额':'参加讲法会')+'</button></div>'}else actions.innerHTML+='<div class="section-tip">下一轮宗门内部议事/小比预计在约 '+Math.max(0,(state.world.nextSectEventDay||0)-dayNumber())+' 日后出现。</div>';actions.querySelectorAll('[data-sect-remaster]').forEach(b=>b.onclick=()=>chooseSectMentor(b.dataset.sectRemaster));const ib=actions.querySelector('[data-sect-internal]');if(ib)ib.onclick=startSectInternalEvent}

function marketPrices(){const idx=state.world.marketIndex||100,x=factionStandingValue('xuanshui'),m=x>=60 ? 0.90 : x>=25 ? 0.95 : x<=-60 ? 1.20 : x<=-25 ? 1.10 : 1;return {idx,standing:x,modifier:m,herbBuy:Math.max(3,Math.ceil(4*idx/100*m)),herbSell:Math.max(1,Math.floor(3*idx/100)),pillBuy:Math.max(6,Math.ceil(8*idx/100*m))}}
function marketTrend(){const i=state.world.marketIndex||100;return i>=120?'火热':i>=106?'偏贵':i>=94?'平稳':i>=84?'偏低':'低迷'}
function marketTrade(kind,count=1){
 if(state.player.location!=='临江城')return showResult('不在坊市','只有到临江城才能进行坊市交易。','bad');
 count=Math.max(1,Math.floor(count));const p=marketPrices(),pl=state.player;
 if(kind==='buyHerb'){
   const cost=p.herbBuy*count;if(pl.spiritStones<cost)return showResult('灵石不足',`购买 ${count} 株灵草需要 ${cost} 块灵石。`,'bad');
   pl.spiritStones-=cost;pl.herbs+=count;pl.tradeVolume+=cost;addPersonal(`你在临江坊市买下 ${count} 株灵草，花费 ${cost} 块灵石。`,'good');showResult('买入灵草',`灵草 +${count}\n灵石 -${cost}`,'good');
 }else if(kind==='sellHerb'){
   if(pl.herbs<count)return showResult('灵草不足',`你没有 ${count} 株灵草可卖。`,'bad');const gain=p.herbSell*count;pl.herbs-=count;pl.spiritStones+=gain;pl.tradeVolume+=gain;addPersonal(`你在临江坊市卖出 ${count} 株灵草，换得 ${gain} 块灵石。`,'good');showResult('卖出灵草',`灵草 -${count}\n灵石 +${gain}`,'good');
 }else if(kind==='buyPill'){
   const cost=p.pillBuy*count;if(pl.spiritStones<cost)return showResult('灵石不足',`购买 ${count} 份回春散需要 ${cost} 块灵石。`,'bad');pl.spiritStones-=cost;pl.healingPills+=count;pl.tradeVolume+=cost;addPersonal(`你在药铺买下 ${count} 份回春散，花费 ${cost} 块灵石。`,'good');showResult('购买回春散',`回春散 +${count}\n灵石 -${cost}`,'good');
 }else return;
 save();render()
}
function useHealingPill(){
 const pl=state.player;if(pl.healingPills<=0)return showResult('没有药物','你身上没有回春散。','bad');if(pl.hp>=maxHp()&&(pl.injury||0)===0)return showResult('无需用药','你现在气血充盈，也没有伤势。');
 const beforeHp=pl.hp,beforeInjury=pl.injury||0;pl.healingPills--;pl.hp=Math.min(maxHp(),pl.hp+Math.ceil(maxHp()*.42));if(pl.injury>0)pl.injury--;addPersonal(`你服下一份回春散，气血恢复，伤势由${['无伤','轻伤','重伤','濒死'][beforeInjury]}缓解为${injuryLabel()}。`,'good');save();render();showResult('服用回春散',`气血 +${pl.hp-beforeHp}\n伤势：${['无伤','轻伤','重伤','濒死'][beforeInjury]} → ${injuryLabel()}\n剩余回春散 ${pl.healingPills}`,'good')
}
function renderMarket(){
 const info=$('marketInfo'),actions=$('marketActions');if(!info||!actions)return;const p=marketPrices(),pl=state.player,here=pl.location==='临江城';
 info.innerHTML=`<div class="kv"><span>临江坊市行情</span><b>${marketTrend()} · 指数 ${p.idx}</b></div><div class="kv"><span>灵草买入 / 卖出</span><b>${p.herbBuy} / ${p.herbSell} 灵石</b></div><div class="kv"><span>回春散</span><b>${p.pillBuy} 灵石 / 份</b></div><div class="kv"><span>随身回春散</span><b>${pl.healingPills}</b></div><div class="kv"><span>累计交易额</span><b>${pl.tradeVolume}</b></div>`;
 actions.innerHTML=here?`<div class="event-actions"><button data-market="buyHerb">买1株灵草</button><button data-market="buyHerb5">买5株灵草</button><button data-market="sellHerb">卖1株灵草</button><button data-market="sellHerb5">卖5株灵草</button><button data-market="buyPill">买1份回春散</button>${pl.healingPills>0?'<button data-market="usePill">服用回春散</button>':''}</div>`:`<div class="section-tip">交易需要前往【临江城】。${pl.healingPills>0?'你仍可使用随身携带的回春散。':''}</div>${pl.healingPills>0?'<div class="event-actions"><button data-market="usePill">服用回春散</button></div>':''}`;
 actions.querySelectorAll('[data-market]').forEach(b=>b.onclick=()=>{const k=b.dataset.market;if(k==='buyHerb')marketTrade('buyHerb',1);else if(k==='buyHerb5')marketTrade('buyHerb',5);else if(k==='sellHerb')marketTrade('sellHerb',1);else if(k==='sellHerb5')marketTrade('sellHerb',5);else if(k==='buyPill')marketTrade('buyPill',1);else if(k==='usePill')useHealingPill()})
}


