const V33_MATERIAL_BY_ID=Object.freeze(Object.fromEntries(V33_MATERIAL_CATALOG.map(x=>[x.id,x])));
const V33_RECIPE_BY_ID=Object.freeze(Object.fromEntries(V33_RECIPE_CATALOG.map(x=>[x.id,x])));
const V33_LEGACY_PILL_FIELDS=Object.freeze({'recipe-healing':'healingPills','recipe-qi':'qiPills','recipe-golden':'goldenPills','recipe-soul':'soulPills'});
const V33_GRADE_META=Object.freeze({common:{name:'普通',power:1,tox:.96,rank:0},fine:{name:'上品',power:1.12,tox:.86,rank:1},superior:{name:'极品',power:1.26,tox:.75,rank:2},perfect:{name:'丹纹',power:1.42,tox:.62,rank:3}});
function v33EmptyPillStack(){return {common:0,fine:0,superior:0,perfect:0}}
function ensureV33AlchemyShape(){
 if(!state?.player)return false;const p=state.player;
 if(!p.materialInventoryById||typeof p.materialInventoryById!=='object'||Array.isArray(p.materialInventoryById))p.materialInventoryById={};
 for(const m of V33_MATERIAL_CATALOG){if(m.legacyField)p.materialInventoryById[m.id]=Math.max(0,Number(p[m.legacyField])||0);else if(p.materialInventoryById[m.id]==null)p.materialInventoryById[m.id]=0}
 if(!p.pillInventoryById||typeof p.pillInventoryById!=='object'||Array.isArray(p.pillInventoryById)){p.pillInventoryById={};for(const r of V33_RECIPE_CATALOG){const s=v33EmptyPillStack(),field=V33_LEGACY_PILL_FIELDS[r.id];if(field)s.common=Math.max(0,Number(p[field])||0);p.pillInventoryById[r.id]=s}}
 for(const r of V33_RECIPE_CATALOG){const old=p.pillInventoryById[r.id];if(!old||typeof old!=='object'||Array.isArray(old))p.pillInventoryById[r.id]=v33EmptyPillStack();else for(const g of Object.keys(V33_GRADE_META))p.pillInventoryById[r.id][g]=Math.max(0,Number(p.pillInventoryById[r.id][g])||0)}
 if(!Array.isArray(p.knownRecipeIds))p.knownRecipeIds=[];for(const r of V33_RECIPE_CATALOG)if(r.knownByDefault===true&&!p.knownRecipeIds.includes(r.id))p.knownRecipeIds.push(r.id);
 p.knownRecipeIds=[...new Set(p.knownRecipeIds.filter(id=>V33_RECIPE_BY_ID[id]))];
 if(p.pillToxicity==null)p.pillToxicity=0;p.pillToxicity=clamp(Number(p.pillToxicity)||0,0,120);
 if(!p.pillToleranceById||typeof p.pillToleranceById!=='object'||Array.isArray(p.pillToleranceById))p.pillToleranceById={};
 if(!p.alchemyBuffs||typeof p.alchemyBuffs!=='object'||Array.isArray(p.alchemyBuffs))p.alchemyBuffs={};
 if(!p.alchemyBestQualityByRecipe||typeof p.alchemyBestQualityByRecipe!=='object'||Array.isArray(p.alchemyBestQualityByRecipe))p.alchemyBestQualityByRecipe={};
 if(p.alchemySuccesses==null)p.alchemySuccesses=0;if(p.alchemyFailures==null)p.alchemyFailures=0;if(p.pillsConsumed==null)p.pillsConsumed=0;if(p.lifeExtensionPillsUsed==null)p.lifeExtensionPillsUsed=0;
 return syncV33AlchemyState()
}
function syncV33AlchemyState(){if(!state?.player)return false;const p=state.player;for(const m of V33_MATERIAL_CATALOG){if(m.legacyField)p.materialInventoryById[m.id]=Math.max(0,Number(p[m.legacyField])||0);else p.materialInventoryById[m.id]=Math.max(0,Number(p.materialInventoryById[m.id])||0)}for(const [id,field] of Object.entries(V33_LEGACY_PILL_FIELDS)){const s=p.pillInventoryById[id]||v33EmptyPillStack();p[field]=Object.values(s).reduce((a,n)=>a+(Number(n)||0),0)}p.materialCountsById={...p.materialInventoryById};p.itemCountsById={};for(const r of V33_RECIPE_CATALOG)p.itemCountsById[r.itemId]=v33PillCount(r.id);return true}
function v33MaterialCount(id){ensureV33AlchemyShape();return Math.max(0,Number(state.player.materialInventoryById[id])||0)}
function v33AddMaterial(id,n=1){ensureV33AlchemyShape();const m=V33_MATERIAL_BY_ID[id],p=state.player;if(!m||!n)return 0;if(m.legacyField){p[m.legacyField]=Math.max(0,(Number(p[m.legacyField])||0)+n);p.materialInventoryById[id]=p[m.legacyField]}else p.materialInventoryById[id]=Math.max(0,(Number(p.materialInventoryById[id])||0)+n);return v33MaterialCount(id)}
function v33PillCount(id){const s=state?.player?.pillInventoryById?.[id];return s?Object.values(s).reduce((a,n)=>a+(Number(n)||0),0):0}
function v33HighestPillGrade(id){const s=state.player.pillInventoryById[id]||{};return ['perfect','superior','fine','common'].find(g=>(s[g]||0)>0)||null}
function v33IngredientText(r){return Object.entries(r.ingredients||{}).map(([id,n])=>(V33_MATERIAL_BY_ID[id]?.name||id)+'×'+n).join(' · ')}
function v33HasIngredients(r){return Object.entries(r.ingredients||{}).every(([id,n])=>v33MaterialCount(id)>=n)}
function v33SpendIngredients(r){for(const [id,n] of Object.entries(r.ingredients||{}))v33AddMaterial(id,-n)}
function v33RecipeKnown(id){ensureV33AlchemyShape();return state.player.knownRecipeIds.includes(id)}
function v33LearnCostText(r){const c=r.learnCost||{};return (c.stones?'灵石'+c.stones:'')+(c.insight?' · 悟道'+c.insight:'')||'无'}
function learnV33Recipe(id,force=false){ensureV33AlchemyShape();const r=V33_RECIPE_BY_ID[id],p=state.player;if(!r)return 'missing';if(p.knownRecipeIds.includes(id))return 'known';if(!force){if(p.realmIndex<r.unlock)return 'realm';if(!(r.sources||[]).includes(p.location))return 'location';const c=r.learnCost||{};if(p.spiritStones<(c.stones||0)||p.insight<(c.insight||0))return 'cost';p.spiritStones-=c.stones||0;p.insight-=c.insight||0;advanceDays(1);if(state.flags.dead)return 'dead'}p.knownRecipeIds.push(id);addPersonal('【丹方】你掌握了《'+r.name+'》丹方。','major');save();render();return 'learned'}
function v33AlchemyChance(r){const p=state.player,prof=Number(p.alchemyProf)||0,realmEdge=Math.max(0,r.unlock-p.realmIndex)*.02,sect=p.sectRank==='内门弟子'?.04:p.sectRank==='真传弟子'?.06:0;return clamp((r.base||.5)+Math.min(.34,prof/900)+sect-realmEdge,.22,.96)}
function v33RollGrade(r,forced=null){if(forced&&V33_GRADE_META[forced])return forced;const prof=Number(state.player.alchemyProf)||0,x=rand(),high=r.unlock>=15;if(x<clamp((prof-(high?260:120))/2600,.01,.10))return 'perfect';if(x<clamp(.05+prof/1500,.06,.24))return 'superior';if(x<clamp(.22+prof/1000,.24,.54))return 'fine';return 'common'}
function brewV33Alchemy(id,opts={}){ensureV33AlchemyShape();const r=V33_RECIPE_BY_ID[id],p=state.player;if(!r)return 'missing';if(!p.knownRecipeIds.includes(id)&&!opts.force)return 'unknown';if(!opts.force&&p.realmIndex<r.unlock)return 'realm';if(!opts.force&&!v33HasIngredients(r))return 'cost';if(!opts.force)v33SpendIngredients(r);p.alchemyBatches=(p.alchemyBatches||0)+1;if(!opts.noTime){advanceDays(r.days||1);if(state.flags.dead)return 'dead'}const chance=opts.forceSuccess===true?1:opts.forceSuccess===false?0:v33AlchemyChance(r),success=rand()<chance;if(!success){p.alchemyProf=(p.alchemyProf||0)+(r.unlock>=15?6:4);p.alchemyFailures++;addPersonal('炼制【'+r.name+'】失败，药性冲突，材料尽毁。','bad');save();render();return 'failed'}const grade=v33RollGrade(r,opts.grade),stack=p.pillInventoryById[id];stack[grade]=(stack[grade]||0)+1;p.alchemyProf=(p.alchemyProf||0)+(r.unlock>=19?16:r.unlock>=15?13:8);p.alchemySuccesses++;const old=p.alchemyBestQualityByRecipe[id],oldRank=old?(V33_GRADE_META[old]?.rank??-1):-1;if(V33_GRADE_META[grade].rank>oldRank)p.alchemyBestQualityByRecipe[id]=grade;addPersonal('【炼丹】'+r.name+'炼成，品质【'+V33_GRADE_META[grade].name+'】。','good');save();render();return grade}
function v33ActiveBuff(key){ensureV33AlchemyShape();const b=state.player.alchemyBuffs[key];if(!b)return null;if((b.expiresDay||0)<dayNumber()){delete state.player.alchemyBuffs[key];return null}return b}
function v33BuffValue(key){return Number(v33ActiveBuff(key)?.value)||0}
function v33BuffMultiplier(key){return Math.max(.25,1+v33BuffValue(key))}
function v33ApplyBuffs(buff={},days=1,scale=1,source='丹药'){const p=state.player,expires=dayNumber()+Math.max(1,days);for(const [key,raw] of Object.entries(buff)){const value=Number(raw)*scale,old=v33ActiveBuff(key);let keep=value;if(old){if(key==='incoming')keep=Math.min(old.value,value);else keep=Math.max(old.value,value)}p.alchemyBuffs[key]={value:keep,expiresDay:Math.max(expires,old?.expiresDay||0),source}}}
function v33DecayAlchemy(days=1){ensureV33AlchemyShape();const p=state.player;p.pillToxicity=Math.max(0,p.pillToxicity-Math.max(1,Math.floor(days*1.8)));const decay=Math.floor(days/3);if(decay>0)for(const id of Object.keys(p.pillToleranceById))p.pillToleranceById[id]=Math.max(0,(p.pillToleranceById[id]||0)-decay);for(const key of Object.keys(p.alchemyBuffs))v33ActiveBuff(key);return p.pillToxicity}
function v33ToxicityLabel(){const n=state.player.pillToxicity||0;return n>=100?'丹毒深重':n>=80?'丹毒过量':n>=55?'丹毒明显':n>=30?'略有丹毒':'清净'}
function useV33Pill(id,grade=null,force=false){ensureV33AlchemyShape();const r=V33_RECIPE_BY_ID[id],p=state.player;if(!r)return 'missing';grade=grade||v33HighestPillGrade(id);if(!force&&(!grade||(p.pillInventoryById[id][grade]||0)<=0))return 'none';if(!grade)grade='common';if(!force&&p.pillToxicity>=100&&!(r.effect?.toxicity<0))return 'toxicity';if(r.effect?.path&&p.daoPath!==r.effect.path&&!force)return 'path';if(r.effect?.maxUses&&p.lifeExtensionPillsUsed>=r.effect.maxUses&&!force)return 'maxUses';if(!force)p.pillInventoryById[id][grade]--;const meta=V33_GRADE_META[grade]||V33_GRADE_META.common,tolerance=Number(p.pillToleranceById[id])||0,toxAdd=Math.max(0,Math.round((r.toxicity||0)*meta.tox+tolerance*1.5)),toxPenalty=p.pillToxicity>=80?.66:p.pillToxicity>=55?.82:1,scale=meta.power*toxPenalty,e=r.effect||{};let notes=[];
 if(e.hp){const before=p.hp,gain=Math.max(1,Math.floor(maxHp()*e.hp*scale));p.hp=Math.min(maxHp(),p.hp+gain);notes.push('气血 +'+(p.hp-before))}
 if(e.qi){const before=p.qi,gain=Math.max(1,Math.floor(maxQi()*e.qi*scale));p.qi=Math.min(maxQi(),p.qi+gain);notes.push('灵力 +'+(p.qi-before))}
 if(e.injury){const before=p.injury||0;p.injury=clamp(before+Math.round(e.injury),0,3);if(before!==p.injury)notes.push('伤势 '+before+'→'+p.injury)}
 if(e.progress){const before=p.progress,gain=Math.max(1,Math.floor(realm().need*e.progress*scale));p.progress=Math.min(realm().need,p.progress+gain);notes.push('修为 +'+(p.progress-before))}
 if(e.manualProf){p.manualProf+=(e.manualProf*scale)|0;notes.push('功法熟练 +'+((e.manualProf*scale)|0))}
 if(e.insight){const n=Math.max(1,Math.floor(e.insight*scale));p.insight+=n;notes.push('悟道 +'+n)}
 if(e.toxicity){p.pillToxicity=clamp(p.pillToxicity+Math.round(e.toxicity*scale),0,120);notes.push('丹毒 '+(e.toxicity<0?'下降':'变化'))}
 if(e.lifespan){const n=Math.max(1,Math.floor(e.lifespan));p.lifespan+=n;p.lifeExtensionPillsUsed++;notes.push('寿元 +'+n+'年')}
 if(e.buff)v33ApplyBuffs(e.buff,e.buffDays||5,scale,r.name);
 p.pillToxicity=clamp(p.pillToxicity+toxAdd,0,120);p.pillToleranceById[id]=Math.min(20,tolerance+1);p.pillsConsumed++;syncV33AlchemyState();addPersonal('你服下【'+V33_GRADE_META[grade].name+'·'+r.name+'】。'+notes.join('，')+'。当前丹毒 '+p.pillToxicity+'。',toxAdd>=18?'bad':'good');save();render();return {grade,toxicity:p.pillToxicity,notes}
}
function useHealingPill(){return useV33Pill('recipe-healing')}
function useQiPill(){return useV33Pill('recipe-qi')}
function useGoldenPill(){return useV33Pill('recipe-golden')}
function useSoulPill(){return useV33Pill('recipe-soul')}
function alchemyChance(r){const id=r?.recipeId||r?.id||r?.legacyRecipeId,rec=V33_RECIPE_BY_ID[id]||V33_RECIPE_CATALOG.find(x=>x.name===r?.name);return rec?v33AlchemyChance(rec):.5}
function alchemyGradeChance(){return clamp(.12+(state.player.alchemyProf||0)/1600,.12,.42)}
function alchemyCostText(r){const rec=V33_RECIPE_BY_ID[r?.recipeId||r?.id]||r;return v33IngredientText(rec)}
function alchemyHasCost(r){const rec=V33_RECIPE_BY_ID[r?.recipeId||r?.id]||r;return v33HasIngredients(rec)}
function spendAlchemyCost(r){const rec=V33_RECIPE_BY_ID[r?.recipeId||r?.id]||r;return v33SpendIngredients(rec)}
function brewAlchemy(id){const r=V33_RECIPE_BY_ID[id]||V33_RECIPE_CATALOG.find(x=>x.legacyKey===id)||V33_RECIPE_CATALOG.find(x=>x.id==='recipe-'+id);const rid=r?.id||id,res=brewV33Alchemy(rid);if(res==='failed')showResult('炼丹失败','材料已经消耗，炼丹熟练度仍有少量增长。','bad');else if(['missing','unknown','realm','cost','dead'].includes(res))showResult('无法炼制','当前条件不足：'+res,'bad');else showResult('炼丹成功','【'+V33_RECIPE_BY_ID[rid].name+'】·'+V33_GRADE_META[res].name+'\n炼丹熟练度 '+state.player.alchemyProf,'good');return res}
function v33MaterialCandidates(location=state.player.location,source='explore',enemy=null){return V33_MATERIAL_CATALOG.filter(m=>m.named&&(m.locations||[]).includes(location)&&state.player.realmIndex+2>=m.minRealm&&(source!=='combat'||!(m.combatKinds||[]).length||(m.combatKinds||[]).includes(enemy?.kind)))}
function gatherV33Material(location=state.player.location,forcedId=null,source='explore',enemy=null){ensureV33AlchemyShape();let row=forcedId?V33_MATERIAL_BY_ID[forcedId]:null;if(row&&(!(row.locations||[]).includes(location)||!row.named))return null;if(!row){const c=v33MaterialCandidates(location,source,enemy);if(!c.length)return null;const weighted=[];for(const m of c){const w=m.qualityId==='di'?1:m.qualityId==='xuan'?3:m.qualityId==='huang'?6:9;for(let i=0;i<w;i++)weighted.push(m)}row=pick(weighted)}const n=row.qualityId==='fan'&&rand()<.35?2:1;v33AddMaterial(row.id,n);return {id:row.id,name:row.name,count:n,source,location}}
function onV33CombatWin(e){if(!e||e.nonLethal)return null;const chance=clamp(.28+(e.realm||0)*.018,.28,.64);if(rand()>=chance)return null;const d=gatherV33Material(state.player.location,null,'combat',e);if(d)addPersonal('【材料掉落】从'+e.name+'身上取得 '+d.name+' ×'+d.count+'。','good');return d}
function v33MaterialDropEntries(e){const areas=e.areas||[],rows=V33_MATERIAL_CATALOG.filter(m=>m.named&&(m.locations||[]).some(x=>areas.includes(x))&&m.minRealm<=Math.max(0,(e.realm||0)+2)&&(!(m.combatKinds||[]).length||(m.combatKinds||[]).includes(e.kind))).slice(0,8);return rows.map(m=>({materialId:m.id,min:0,max:m.qualityId==='di'?1:m.qualityId==='xuan'?1:2,mode:'named-source'}))}
