 const rows=V33_RECIPE_CATALOG.filter(r=>p.knownRecipeIds.includes(r.id)||(r.sources||[]).includes(here));actions.innerHTML=rows.map(r=>{const known=p.knownRecipeIds.includes(r.id),count=v33PillCount(r.id),canRealm=p.realmIndex>=r.unlock,canCost=v33HasIngredients(r),grade=v33HighestPillGrade(r.id);let buttons='';if(!known)buttons='<button data-v33-learn="'+r.id+'" '+(canRealm?'':'disabled')+'>参悟丹方 · '+esc(v33LearnCostText(r))+'</button>';else buttons='<button data-v33-brew="'+r.id+'" '+(canRealm&&canCost?'':'disabled')+'>开炉炼制 · '+esc(v33IngredientText(r))+'</button>';if(count>0)buttons+='<button data-v33-use="'+r.id+'">服用 '+esc(V33_GRADE_META[grade]?.name||'丹药')+' · 余'+count+'</button>';return '<div class="skill-card"><div class="skill-head"><b>【'+esc(r.name)+'】</b><span>'+esc(r.qualityId)+' · '+REALMS[Math.min(r.unlock,REALMS.length-1)].name+'</span></div><div class="skill-desc">'+esc(r.desc)+'<br>丹方来源：'+esc((r.sources||[]).join(' / '))+'<br>材料：'+esc(v33IngredientText(r))+'<br>成功率 '+Math.round(v33AlchemyChance(r)*100)+'% · 最佳品质 '+esc(v33RecipeQualityName(r.id))+' · 基础丹毒 '+r.toxicity+'</div><div class="event-actions">'+buttons+'</div></div>'}).join('');
